// Mava edge relay (generated by edge/build.mjs from edge/src; do not edit).
// ---- assets (server/admin) ----
const PANEL_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Mava relay admin</title>\n<link rel=\"icon\" type=\"image/png\" href=\"data:image/png;base64,\">\n<style>\n  :root { --bg:#f5f6f8; --panel:#fff; --ink:#1b1f24; --muted:#5f6b7a; --line:#dde2e8; --accent:#0f766e; --accent-ink:#fff; --warn:#b42318; --warn-bg:#fdecea; --ok:#127a3d; }\n  @media (prefers-color-scheme: dark) { :root { --bg:#0f1317; --panel:#171c21; --ink:#e6eaee; --muted:#93a0ad; --line:#2a323a; --accent:#2dd4bf; --accent-ink:#04211e; --warn:#ff8a7a; --warn-bg:#3a1714; --ok:#4ade80; } }\n  * { box-sizing: border-box; }\n  body { margin:0; background:var(--bg); color:var(--ink); font:15px/1.5 system-ui, -apple-system, \"Segoe UI\", Vazirmatn, Tahoma, sans-serif; }\n  header { display:flex; align-items:center; gap:12px; padding:14px 20px; background:var(--panel); border-bottom:1px solid var(--line); }\n  header h1 { font-size:17px; margin:0; flex:1; }\n  header .who { color:var(--muted); font-size:13px; font-family:ui-monospace, monospace; }\n  main { max-width:960px; margin:0 auto; padding:20px 16px 60px; }\n  section { background:var(--panel); border:1px solid var(--line); border-radius:12px; padding:18px 20px; margin-bottom:16px; }\n  h2 { font-size:15px; margin:0 0 12px; }\n  .grid { display:grid; grid-template-columns:repeat(auto-fit, minmax(150px, 1fr)); gap:10px; }\n  .stat { border:1px solid var(--line); border-radius:10px; padding:10px 12px; }\n  .stat b { display:block; font-size:20px; font-variant-numeric:tabular-nums; }\n  .stat span { color:var(--muted); font-size:12px; }\n  label { display:block; font-size:13px; color:var(--muted); margin:10px 0 4px; }\n  input, textarea { width:100%; padding:9px 11px; border:1px solid var(--line); border-radius:8px; background:var(--bg); color:var(--ink); font:inherit; }\n  textarea { min-height:70px; font-family:ui-monospace, monospace; font-size:13px; }\n  .row { display:grid; grid-template-columns:repeat(auto-fit, minmax(180px, 1fr)); gap:0 14px; }\n  button { padding:9px 16px; border-radius:8px; border:1px solid var(--accent); background:var(--accent); color:var(--accent-ink); font:inherit; font-weight:600; cursor:pointer; min-height:40px; }\n  button.ghost { background:transparent; color:var(--accent); }\n  button.danger { background:transparent; color:var(--warn); border-color:var(--warn); }\n  button:disabled { opacity:.5; cursor:default; }\n  .actions { display:flex; gap:10px; flex-wrap:wrap; margin-top:14px; align-items:center; }\n  .msg { font-size:14px; color:var(--muted); }\n  .err { color:var(--warn); }\n  .banner { background:var(--warn-bg); color:var(--warn); border-radius:10px; padding:10px 14px; margin-bottom:16px; font-size:14px; }\n  table { width:100%; border-collapse:collapse; font-size:13px; }\n  th, td { text-align:start; padding:7px 6px; border-bottom:1px solid var(--line); }\n  th { color:var(--muted); font-weight:500; }\n  td.mono, .mono { font-family:ui-monospace, monospace; overflow-wrap:anywhere; }\n  .tag { font-size:11px; border:1px solid var(--line); border-radius:999px; padding:1px 8px; color:var(--muted); margin-inline-start:6px; }\n  #login { max-width:420px; margin:40px auto; }\n  .hint { font-size:13px; color:var(--muted); margin:6px 0 0; }\n  .scroll { overflow-x:auto; }\n</style>\n</head>\n<body>\n<header>\n  <img src=\"data:image/png;base64,\" alt=\"\" width=\"28\" height=\"28\" style=\"border-radius:7px\">\n  <h1 id=\"title\">Mava relay admin</h1>\n  <span class=\"who\" id=\"who\"></span>\n  <button class=\"ghost\" id=\"btnLogout\" hidden>Log out</button>\n</header>\n<main>\n  <section id=\"login\" hidden>\n    <h2>Log in</h2>\n    <p class=\"hint\">Enter your Mava account id. The relay sends a one-time code to that account as a Mava message.</p>\n    <label for=\"loginId\">Account id</label>\n    <input id=\"loginId\" class=\"mono\" placeholder=\"32 hex characters\" autocomplete=\"username\" spellcheck=\"false\">\n    <div class=\"actions\"><button id=\"btnCode\">Send code</button></div>\n    <div id=\"codeStep\" hidden>\n      <label for=\"loginCode\">Code from Mava</label>\n      <input id=\"loginCode\" inputmode=\"numeric\" autocomplete=\"one-time-code\" maxlength=\"12\">\n      <div class=\"actions\"><button id=\"btnLogin\">Log in</button></div>\n    </div>\n    <p class=\"msg\" id=\"loginMsg\" role=\"status\"></p>\n  </section>\n\n  <div id=\"dash\" hidden>\n    <div class=\"banner\" id=\"insecure\" hidden>This page is not served over HTTPS: the login code and session can be read on the network. Put the relay behind Caddy (server/deploy/Caddyfile) with a domain.</div>\n\n    <section>\n      <h2 id=\"relayName\">Relay</h2>\n      <div class=\"grid\" id=\"stats\"></div>\n      <p class=\"hint mono\" id=\"relayKey\"></p>\n    </section>\n\n    <section id=\"tripBox\" hidden>\n      <h2>Trip</h2>\n      <p id=\"tripInfo\"></p>\n      <p><a href=\"/admin/trip\">Open the trip map</a> (paste the map key from the leader's app: Trips → Key for the web map).</p>\n    </section>\n\n    <section>\n      <h2>Settings</h2>\n      <p class=\"hint\">Saved settings override relay.json and apply after a restart (the important-file rules apply at once). Empty fields keep relay.json's value. Relays carry only files the sender marked important; normal files go phone to phone.</p>\n      <div class=\"row\">\n        <div><label for=\"s_pow_bits\">Proof-of-work bits (0–28)</label><input id=\"s_pow_bits\" type=\"number\" min=\"0\" max=\"28\"></div>\n        <div><label for=\"s_ttl_hours\">Message keep time, hours</label><input id=\"s_ttl_hours\" type=\"number\" min=\"1\"></div>\n      </div>\n      <h2 style=\"margin-top:18px\">Media</h2>\n      <div class=\"row\">\n        <div><label for=\"s_media_max_mb\">Largest file, MB (0 = media off)</label><input id=\"s_media_max_mb\" type=\"number\" min=\"0\" max=\"64\"></div>\n        <div><label for=\"s_media_store_mb\">Total storage, MB</label><input id=\"s_media_store_mb\" type=\"number\" min=\"16\"></div>\n        <div><label for=\"s_media_important_per_day\">Important files per account per day</label><input id=\"s_media_important_per_day\" type=\"number\" min=\"1\" max=\"1000\"></div>\n        <div><label for=\"s_media_important_hours\">Keep important files, hours</label><input id=\"s_media_important_hours\" type=\"number\" min=\"1\" max=\"720\"></div>\n        <div><label for=\"s_media_new_account_days\">New account: younger than, days</label><input id=\"s_media_new_account_days\" type=\"number\" min=\"0\" max=\"365\"></div>\n        <div><label for=\"s_media_new_account_per_day\">New account: files per day</label><input id=\"s_media_new_account_per_day\" type=\"number\" min=\"0\" max=\"1000\"></div>\n        <div><label for=\"s_media_pow_base_bits\">Proof-of-work base bits</label><input id=\"s_media_pow_base_bits\" type=\"number\" min=\"0\" max=\"30\"></div>\n        <div><label for=\"s_media_pow_max_bits\">Proof-of-work at most, bits</label><input id=\"s_media_pow_max_bits\" type=\"number\" min=\"0\" max=\"32\"></div>\n      </div>\n      <label for=\"s_media_pow_age_tiers\">Extra work for young accounts (days:bits, e.g. 3:3, 30:2, 180:1)</label>\n      <input id=\"s_media_pow_age_tiers\" spellcheck=\"false\">\n      <p class=\"hint\">Every important file needs proof-of-work: base bits + the extra for the account's age + 1 per file it sent today on any relay + up to 2 when storage fills. Each bit doubles the work. These apply at once.</p>\n      <label for=\"s_media_accounts\">Accounts allowed to upload media (one id per line; empty = anyone)</label>\n      <textarea id=\"s_media_accounts\" spellcheck=\"false\"></textarea>\n      <h2 style=\"margin-top:18px\">TURN for this relay's admins</h2>\n      <p class=\"hint\" id=\"turnSummary\"></p>\n      <label><input type=\"checkbox\" id=\"s_turn_enabled\" style=\"width:auto\"> Let this relay's admins relay calls and direct sessions through it when no direct path exists</label>\n      <div class=\"row\">\n        <div><label for=\"s_turn_max_sessions\">Sessions at once</label><input id=\"s_turn_max_sessions\" type=\"number\" min=\"1\" max=\"1000\"></div>\n        <div><label for=\"s_turn_max_kbps\">Speed per session, kbit/s</label><input id=\"s_turn_max_kbps\" type=\"number\" min=\"16\"></div>\n        <div><label for=\"s_turn_monthly_gb\">Traffic per month, GB</label><input id=\"s_turn_monthly_gb\" type=\"number\" min=\"1\"></div>\n      </div>\n      <label><input type=\"checkbox\" id=\"s_log\" style=\"width:auto\"> Request logs (off is safer)</label>\n      <div class=\"actions\">\n        <button id=\"btnSave\">Save</button>\n        <button class=\"ghost\" id=\"btnRestart\">Restart relay</button>\n        <span class=\"msg\" id=\"saveMsg\" role=\"status\"></span>\n      </div>\n    </section>\n\n    <section>\n      <h2>Admins</h2>\n      <p class=\"hint\">Admins log in with a code sent to their Mava account. The owner can't be removed. Also: <span class=\"mono\">meshmsg-relay admin add|rm|list</span>.</p>\n      <table><tbody id=\"admins\"></tbody></table>\n      <div class=\"actions\">\n        <input id=\"newAdmin\" class=\"mono\" placeholder=\"account id\" style=\"flex:1; min-width:220px\" spellcheck=\"false\">\n        <button id=\"btnAddAdmin\">Add admin</button>\n      </div>\n      <p class=\"msg\" id=\"adminMsg\" role=\"status\"></p>\n    </section>\n\n    <section>\n      <h2>Usage ledger</h2>\n      <p class=\"hint\" id=\"ledgerSummary\"></p>\n      <div class=\"scroll\"><table>\n        <thead><tr><th>Source</th><th>Valid</th><th>Invalid</th><th>Last</th><th></th></tr></thead>\n        <tbody id=\"ledger\"></tbody>\n      </table></div>\n    </section>\n\n    <section>\n      <h2>Stored media</h2>\n      <p class=\"hint\" id=\"mediaSummary\"></p>\n      <div class=\"scroll\"><table>\n        <thead><tr><th>File</th><th>Size</th><th>Downloads</th><th>Deleted at the latest</th><th></th></tr></thead>\n        <tbody id=\"media\"></tbody>\n      </table></div>\n    </section>\n  </div>\n</main>\n<script>\n\"use strict\";\nconst $ = (id) => document.getElementById(id);\nasync function api(path, body) {\n  const opts = body === undefined ? {} : {method: \"POST\", headers: {\"Content-Type\": \"application/json\", \"X-Mava-Panel\": \"1\"}, body: JSON.stringify(body)};\n  const r = await fetch(\"/admin/api/\" + path, Object.assign({credentials: \"same-origin\"}, opts));\n  const j = r.status === 204 ? {} : await r.json().catch(() => ({}));\n  if (!r.ok) { const e = new Error(j.error || r.statusText); e.status = r.status; throw e; }\n  return j;\n}\nconst el = (tag, props = {}, ...kids) => { const e = Object.assign(document.createElement(tag), props); e.append(...kids); return e; };\nconst size = (n) => n >= 1 << 30 ? (n / (1 << 30)).toFixed(1) + \" GB\" : n >= 1 << 20 ? (n / (1 << 20)).toFixed(1) + \" MB\" : n >= 1024 ? Math.round(n / 1024) + \" KB\" : n + \" B\";\nconst dur = (s) => { const d = Math.floor(s / 86400), h = Math.floor(s % 86400 / 3600), m = Math.floor(s % 3600 / 60); return (d ? d + \"d \" : \"\") + (d || h ? h + \"h \" : \"\") + m + \"m\"; };\nfunction say(id, text, err) { $(id).textContent = text; $(id).classList.toggle(\"err\", !!err); }\n\nlet lastID = \"\";\ntry { lastID = localStorage.getItem(\"mavaAdminId\") || \"\"; } catch (e) {}\n$(\"loginId\").value = lastID;\n\n$(\"btnCode\").onclick = async () => {\n  $(\"btnCode\").disabled = true;\n  try {\n    const r = await api(\"code\", {id: $(\"loginId\").value});\n    try { localStorage.setItem(\"mavaAdminId\", $(\"loginId\").value.trim()); } catch (e) {}\n    say(\"loginMsg\", r.info); $(\"codeStep\").hidden = false; $(\"loginCode\").focus();\n  } catch (e) { say(\"loginMsg\", e.message, true); }\n  setTimeout(() => $(\"btnCode\").disabled = false, 3000);\n};\n$(\"btnLogin\").onclick = async () => {\n  try { await api(\"login\", {id: $(\"loginId\").value, code: $(\"loginCode\").value}); $(\"loginCode\").value = \"\"; load(); }\n  catch (e) { say(\"loginMsg\", e.message, true); }\n};\n$(\"loginCode\").onkeydown = (e) => { if (e.key === \"Enter\") $(\"btnLogin\").click(); };\n$(\"loginId\").onkeydown = (e) => { if (e.key === \"Enter\") $(\"btnCode\").click(); };\n$(\"btnLogout\").onclick = async () => { await api(\"logout\", {}).catch(() => {}); load(); };\n\nconst fields = [\"pow_bits\", \"ttl_hours\", \"media_max_mb\", \"media_store_mb\", \"media_important_per_day\", \"media_important_hours\",\n  \"media_new_account_days\", \"media_new_account_per_day\", \"media_pow_base_bits\", \"media_pow_max_bits\",\n  \"turn_max_sessions\", \"turn_max_kbps\", \"turn_monthly_gb\"];\nlet state = null;\n\nasync function load() {\n  try { state = await api(\"state\"); }\n  catch (e) {\n    $(\"login\").hidden = false; $(\"dash\").hidden = true; $(\"btnLogout\").hidden = true; $(\"who\").textContent = \"\";\n    if (e.status !== 401) say(\"loginMsg\", e.message, true);\n    return;\n  }\n  $(\"login\").hidden = true; $(\"dash\").hidden = false; $(\"btnLogout\").hidden = false;\n  $(\"who\").textContent = state.you.slice(0, 12) + (state.you === state.owner ? \" · owner\" : \"\");\n  const i = state.info;\n  document.title = \"Mava relay \" + i.Name + \" · admin\";\n  $(\"title\").textContent = \"Mava relay admin · \" + i.Name;\n  $(\"insecure\").hidden = state.secure;\n  $(\"relayName\").textContent = `${i.Name} · region ${i.Region} · v${i.Version}`;\n  $(\"relayKey\").textContent = \"Relay key \" + i.PubKey.slice(0, 32) + \"…  ·  peers: \" + (i.Peers.length ? i.Peers.join(\", \") : \"none\");\n  const m = state.media, st = state.stats;\n  const stat = (v, l) => el(\"div\", {className: \"stat\"}, el(\"b\", {textContent: v}), el(\"span\", {textContent: l}));\n  $(\"stats\").replaceChildren(\n    stat(dur(state.uptime), \"up\"),\n    stat(st.Accepted, \"packets accepted\"),\n    stat(st.Duplicate, \"duplicates\"),\n    stat(st.Rejected, \"rejected\"),\n    stat(st.Purged, \"purged by receipts\"),\n    stat(m.on ? m.count : \"off\", \"media files\"),\n    stat(m.on ? size(m.used) + \" / \" + size(m.cap) : \"—\", \"media storage\"));\n  // Settings: show saved overrides, with the value in use as placeholder.\n  const cur = state.current, saved = state.saved;\n  for (const f of fields) { $(\"s_\" + f).value = saved[f] ?? \"\"; $(\"s_\" + f).placeholder = cur[f] ?? \"\"; }\n  $(\"s_media_accounts\").value = (saved.media_accounts ?? cur.media_accounts ?? []).join(\"\\n\");\n  $(\"s_media_pow_age_tiers\").value = saved.media_pow_age_tiers ?? \"\";\n  $(\"s_media_pow_age_tiers\").placeholder = cur.media_pow_age_tiers ?? \"\";\n  const lg = state.ledger || {};\n  $(\"ledgerSummary\").textContent = `${lg.today || 0} important files today from ${lg.accounts_today || 0} accounts on all relays; ` +\n    `${lg.entries || 0} entries kept, ${lg.accounts_known || 0} accounts with a known age.` +\n    (lg.bad_sources ? ` ${lg.bad_sources} source(s) sent invalid entries.` : \"\");\n  $(\"ledger\").replaceChildren(...(lg.sources || []).map((s) => el(\"tr\", {},\n    el(\"td\", {className: \"mono\", textContent: s.key.length > 40 ? s.key.slice(0, 40) + \"…\" : s.key, title: s.key}),\n    el(\"td\", {textContent: s.valid}),\n    el(\"td\", {textContent: s.invalid}),\n    el(\"td\", {textContent: new Date(s.last).toLocaleString()}),\n    el(\"td\", {textContent: s.blocked ? \"ignored\" : \"\"}))));\n  $(\"s_log\").checked = saved.log ?? cur.log ?? false;\n  $(\"s_turn_enabled\").checked = saved.turn_enabled ?? cur.turn_enabled ?? false;\n  const tu = state.turn;\n  $(\"turnSummary\").textContent = !tu ? \"The UDP reflector isn't running on this relay (port 3478/3479 busy, or \\\"reflector\\\": false).\"\n    : !tu.available ? \"Address reflector on UDP 3478/3479 is on. TURN needs a public IPv4 address (set public_ip in relay.json).\"\n    : `Reflector on. TURN ${tu.enabled ? \"on\" : \"off\"} — ${tu.sessions} live session(s), ${size(tu.month_bytes)} relayed in ${tu.month} (relayed from ${tu.public_ip}). Ordinary users never get TURN.`;\n  const tr = state.trip;\n  $(\"tripBox\").hidden = !(tr && tr.card);\n  if (tr && tr.card) {\n    $(\"tripInfo\").textContent = `${tr.card.name} · until ${new Date(tr.card.ends * 1000).toLocaleString()} · leaders: ` +\n      tr.leaders.map((l) => (l.name || l.id.slice(0, 8)) + (l.admin ? \"\" : \" (no longer an admin)\")).join(\", \");\n  }\n  renderAdmins(state.admins);\n  $(\"mediaSummary\").textContent = m.on\n    ? `${m.count} files, ${size(m.used)} of ${size(m.cap)}. Each is deleted when all its readers downloaded it, or at the time shown.`\n    : \"Media is off on this relay (largest file = 0).\";\n  $(\"media\").replaceChildren(...(m.files || []).map((f) => el(\"tr\", {},\n    el(\"td\", {className: \"mono\", textContent: f.id}),\n    el(\"td\", {textContent: size(f.size)}),\n    el(\"td\", {textContent: f.served + \" / \" + f.readers}),\n    el(\"td\", {textContent: new Date(f.expires).toLocaleString()}),\n    el(\"td\", {}, el(\"button\", {className: \"danger\", textContent: \"Delete\", onclick: async () => {\n      try { await api(\"media/delete\", {id: f.id}); load(); } catch (e) { alert(e.message); }\n    }})))));\n}\n\nfunction renderAdmins(list) {\n  $(\"admins\").replaceChildren(...list.map((id) => el(\"tr\", {},\n    el(\"td\", {className: \"mono\"}, id,\n      ...(id === state.owner ? [el(\"span\", {className: \"tag\", textContent: \"owner\"})] : []),\n      ...(id === state.you ? [el(\"span\", {className: \"tag\", textContent: \"you\"})] : [])),\n    el(\"td\", {style: \"text-align:end\"}, id === state.owner ? \"\" : el(\"button\", {className: \"danger\", textContent: \"Remove\", onclick: async () => {\n      if (!confirm(\"Remove admin \" + id + \"?\")) return;\n      try { renderAdmins((await api(\"admins\", {remove: id})).admins); say(\"adminMsg\", \"\"); } catch (e) { say(\"adminMsg\", e.message, true); }\n    }})))));\n}\n\n$(\"btnAddAdmin\").onclick = async () => {\n  try { renderAdmins((await api(\"admins\", {add: $(\"newAdmin\").value})).admins); $(\"newAdmin\").value = \"\"; say(\"adminMsg\", \"Added.\"); }\n  catch (e) { say(\"adminMsg\", e.message, true); }\n};\n$(\"btnSave\").onclick = async () => {\n  const body = {};\n  for (const f of fields) { const v = $(\"s_\" + f).value.trim(); if (v !== \"\") body[f] = Number(v); }\n  body.media_accounts = $(\"s_media_accounts\").value.split(/[\\s,]+/).filter(Boolean);\n  const tiers = $(\"s_media_pow_age_tiers\").value.trim();\n  if (tiers !== \"\") body.media_pow_age_tiers = tiers;\n  body.log = $(\"s_log\").checked;\n  body.turn_enabled = $(\"s_turn_enabled\").checked;\n  try { say(\"saveMsg\", (await api(\"settings\", body)).info); load(); } catch (e) { say(\"saveMsg\", e.message, true); }\n};\n$(\"btnRestart\").onclick = async () => {\n  if (!confirm(\"Restart the relay now? Clients reconnect by themselves.\")) return;\n  try { say(\"saveMsg\", (await api(\"restart\", {})).info); setTimeout(load, 6000); } catch (e) { say(\"saveMsg\", e.message, true); }\n};\nload();\n</script>\n</body>\n</html>\n";
const TRIPMAP_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Trip map — Mava relay</title>\n<style>\n  :root { --bg:#0b0a14; --card:#15122a; --line:#3b2a6b; --fg:#ece8ff; --muted:#a9a2cf; --accent:#a78bfa; --sos:#dc2626; --ok:#16a34a; }\n  * { box-sizing: border-box; }\n  body { margin:0; font:14px/1.45 system-ui, sans-serif; background:var(--bg); color:var(--fg); }\n  header { padding:10px 14px; border-bottom:1px solid var(--line); display:flex; gap:12px; align-items:center; flex-wrap:wrap; }\n  header h1 { font-size:16px; margin:0; }\n  header a { color:var(--accent); }\n  .muted { color:var(--muted); }\n  main { display:grid; grid-template-columns: minmax(260px, 340px) 1fr; height: calc(100vh - 52px); }\n  @media (max-width: 760px) { main { grid-template-columns: 1fr; grid-template-rows: auto 60vh; height:auto; } }\n  aside { overflow:auto; border-right:1px solid var(--line); padding:10px; }\n  #map { position:relative; overflow:hidden; background:#1e1a3a; touch-action:none; cursor:grab; }\n  #tiles, #overlay { position:absolute; inset:0; }\n  #tiles img { position:absolute; width:256px; height:256px; user-select:none; -webkit-user-drag:none; }\n  #overlay svg { position:absolute; inset:0; width:100%; height:100%; pointer-events:none; }\n  .pin { position:absolute; transform:translate(-50%,-100%); background:var(--accent); color:#000; border-radius:10px; padding:1px 6px; font-size:12px; white-space:nowrap; pointer-events:auto; cursor:pointer; }\n  .pin.sos { background:var(--sos); color:#fff; font-weight:600; animation: blink 1s infinite; }\n  .pin.old { background:#6b7280; color:#fff; }\n  .pin.me { background:#38bdf8; }\n  @keyframes blink { 50% { opacity:.55; } }\n  .zoom { position:absolute; right:10px; top:10px; display:flex; flex-direction:column; gap:4px; z-index:5; }\n  .zoom button { width:32px; height:32px; font-size:18px; }\n  .attr { position:absolute; right:4px; bottom:2px; font-size:11px; background:rgba(255,255,255,.75); color:#000; padding:0 4px; z-index:5; }\n  .attr a { color:#000; }\n  button, input { font:inherit; }\n  button { background:var(--card); color:var(--fg); border:1px solid var(--line); border-radius:6px; padding:5px 10px; cursor:pointer; }\n  input { background:#0f0d1f; color:var(--fg); border:1px solid var(--line); border-radius:6px; padding:6px; width:100%; }\n  .card { background:var(--card); border:1px solid var(--line); border-radius:8px; padding:8px 10px; margin-bottom:8px; }\n  .m { cursor:pointer; }\n  .m.sos { border-color:var(--sos); }\n  .badge { display:inline-block; border-radius:4px; padding:0 5px; font-size:11px; margin-left:4px; }\n  .badge.sos { background:var(--sos); color:#fff; }\n  .badge.stop { background:#6b7280; color:#fff; }\n  .err { color:#fca5a5; }\n</style>\n</head>\n<body>\n<header>\n  <h1 id=\"title\">Trip map</h1>\n  <span class=\"muted\" id=\"sub\"></span>\n  <a href=\"/admin\">← admin panel</a>\n</header>\n<main>\n  <aside>\n    <div class=\"card\" id=\"keybox\">\n      <div>Map key (from the leader's app: <i>Trip → Key for the web map</i>). It stays in this browser tab; the relay never sees it.</div>\n      <input id=\"key\" placeholder=\"64 hex characters\" autocomplete=\"off\" spellcheck=\"false\">\n      <div style=\"margin-top:6px; display:flex; gap:6px;\"><button id=\"open\">Open reports</button><button id=\"forget\">Forget key</button></div>\n      <div class=\"err\" id=\"keyerr\"></div>\n    </div>\n    <div id=\"status\" class=\"muted\"></div>\n    <div id=\"members\"></div>\n  </aside>\n  <div id=\"map\">\n    <div id=\"tiles\"></div>\n    <div id=\"overlay\"><svg id=\"svg\"></svg></div>\n    <div class=\"zoom\"><button id=\"zin\">+</button><button id=\"zout\">−</button><button id=\"fit\" title=\"Fit everyone\">⤢</button></div>\n    <div class=\"attr\">© <a href=\"https://www.openstreetmap.org/copyright\" target=\"_blank\" rel=\"noopener\">OpenStreetMap</a> contributors</div>\n  </div>\n</main>\n<script>\n/*TRIPCRYPTO*/\n</script>\n<script>\n'use strict';\nconst $ = (id) => document.getElementById(id);\nlet card = null, pub = null, priv = null, cursor = 0, timer = null;\nconst members = new Map(); // member hash → {latest, track: [{lat, lon, t}]}\nconst seen = new Set();\n\nfunction esc(s) { return String(s).replace(/[&<>\"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' })[c]); }\nfunction ago(t) {\n  const s = Math.max(0, Math.round(Date.now() / 1000 - t));\n  if (s < 90) return s + ' s ago';\n  if (s < 5400) return Math.round(s / 60) + ' min ago';\n  if (s < 172800) return Math.round(s / 3600) + ' h ago';\n  return Math.round(s / 86400) + ' days ago';\n}\n\nasync function api(path) {\n  const r = await fetch(path, { credentials: 'same-origin' });\n  if (r.status === 401) { throw new Error('login'); }\n  if (!r.ok) throw new Error((await r.text()) || r.statusText);\n  return r.json();\n}\n\nasync function load() {\n  try {\n    const st = await api('/admin/api/trip');\n    if (!st.card) { $('status').textContent = 'No trip is running on this relay. A leader starts one from the app.'; $('keybox').hidden = true; return; }\n    card = st.card;\n    pub = TripCrypto.unhex(card.key.slice(0, 64));\n    $('title').textContent = card.name;\n    $('sub').textContent = 'until ' + new Date(card.ends * 1000).toLocaleString() + ' · leaders: ' + card.leaders.map((l) => l.name || l.id.slice(0, 8)).join(', ');\n    const k = sessionStorage.getItem('tripkey:' + st.hash);\n    if (k) { $('key').value = k; useKey(k, st.hash); }\n  } catch (e) {\n    $('status').innerHTML = e.message === 'login' ? 'Log in to the <a href=\"/admin\">admin panel</a> first.' : esc(e.message);\n  }\n}\n\nfunction useKey(k, hash) {\n  $('keyerr').textContent = '';\n  k = k.trim().toLowerCase();\n  if (!/^[0-9a-f]{64}$/.test(k)) { $('keyerr').textContent = 'The key is 64 hex characters.'; return; }\n  const p = TripCrypto.unhex(k);\n  if (TripCrypto.hex(TripCrypto.x25519(p, TripCrypto.BASE)) !== card.key.slice(0, 64)) { $('keyerr').textContent = 'This key does not belong to this trip.'; return; }\n  priv = p;\n  sessionStorage.setItem('tripkey:' + hash, k);\n  $('keybox').hidden = true;\n  poll();\n}\n\nasync function poll() {\n  clearTimeout(timer);\n  try {\n    for (;;) {\n      const r = await api('/admin/api/trip/reports?after=' + cursor);\n      for (const b64 of r.packets) {\n        const raw = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));\n        const rep = await TripCrypto.openReport(priv, pub, raw);\n        if (rep && !seen.has(rep.id)) { seen.add(rep.id); add(rep); }\n      }\n      cursor = r.cursor;\n      if (!r.more) break;\n    }\n    $('status').textContent = members.size + ' member(s) · updated ' + new Date().toLocaleTimeString();\n    render(true);\n  } catch (e) {\n    $('status').textContent = e.message === 'login' ? 'Session ended: log in again in the admin panel.' : 'Error: ' + e.message;\n  }\n  timer = setTimeout(poll, 30000);\n}\n\nfunction add(r) {\n  let m = members.get(r.member);\n  if (!m) { m = { latest: null, track: [], name: r.name, key: r.key }; members.set(r.member, m); }\n  const fix = r.sent - r.fixAge;\n  if (!m.latest || r.sent >= m.latest.sent) {\n    m.latest = r;\n    if (r.name) m.name = r.name;\n    if (!(r.flags & 8)) m.pos = { lat: r.lat, lon: r.lon, t: fix, acc: r.accuracy };\n  }\n  if (!(r.flags & 8)) { m.track.push({ lat: r.lat, lon: r.lon, t: fix }); m.track.sort((a, b) => a.t - b.t); if (m.track.length > 500) m.track.shift(); }\n}\n\nfunction list() {\n  const arr = [...members.entries()].map(([id, m]) => ({ id, ...m }));\n  arr.sort((a, b) => ((b.latest.flags & 1) - (a.latest.flags & 1)) || a.name.localeCompare(b.name));\n  return arr;\n}\n\n// ---- the map: OpenStreetMap tiles, Web Mercator ----\nconst view = { lat: 32.3, lon: 44.2, z: 9 };\nconst TS = 256;\nconst wx = (lon, z) => (lon + 180) / 360 * TS * 2 ** z;\nconst wy = (lat, z) => { const s = Math.sin(lat * Math.PI / 180); return (0.5 - Math.log((1 + s) / (1 - s)) / (4 * Math.PI)) * TS * 2 ** z; };\nconst lonOf = (x, z) => x / (TS * 2 ** z) * 360 - 180;\nconst latOf = (y, z) => { const n = Math.PI - 2 * Math.PI * y / (TS * 2 ** z); return 180 / Math.PI * Math.atan(0.5 * (Math.exp(n) - Math.exp(-n))); };\nlet fitted = false;\n\nfunction fit() {\n  const pts = list().filter((m) => m.pos).map((m) => m.pos);\n  if (!pts.length) return;\n  const el = $('map'), W = el.clientWidth, H = el.clientHeight;\n  let z = 17;\n  for (; z > 2; z--) {\n    const xs = pts.map((p) => wx(p.lon, z)), ys = pts.map((p) => wy(p.lat, z));\n    if (Math.max(...xs) - Math.min(...xs) < W - 80 && Math.max(...ys) - Math.min(...ys) < H - 80) break;\n  }\n  const xs = pts.map((p) => wx(p.lon, z)), ys = pts.map((p) => wy(p.lat, z));\n  view.z = z;\n  view.lon = lonOf((Math.max(...xs) + Math.min(...xs)) / 2, z);\n  view.lat = latOf((Math.max(...ys) + Math.min(...ys)) / 2, z);\n  fitted = true;\n  draw();\n}\n\nfunction draw() {\n  const el = $('map'), W = el.clientWidth, H = el.clientHeight, z = view.z;\n  const cx = wx(view.lon, z), cy = wy(view.lat, z);\n  const left = cx - W / 2, top = cy - H / 2, n = 2 ** z;\n  const tiles = $('tiles');\n  const want = new Set();\n  for (let ty = Math.floor(top / TS); ty <= Math.floor((top + H) / TS); ty++) {\n    if (ty < 0 || ty >= n) continue;\n    for (let tx = Math.floor(left / TS); tx <= Math.floor((left + W) / TS); tx++) {\n      const x = ((tx % n) + n) % n;\n      const key = z + '/' + x + '/' + ty;\n      want.add(key + '@' + tx);\n      let img = tiles.querySelector('img[data-k=\"' + key + '@' + tx + '\"]');\n      if (!img) {\n        img = document.createElement('img');\n        img.dataset.k = key + '@' + tx;\n        img.referrerPolicy = 'strict-origin';\n        img.alt = '';\n        img.src = 'https://tile.openstreetmap.org/' + key + '.png';\n        tiles.appendChild(img);\n      }\n      img.style.left = Math.round(tx * TS - left) + 'px';\n      img.style.top = Math.round(ty * TS - top) + 'px';\n    }\n  }\n  for (const img of [...tiles.children]) if (!want.has(img.dataset.k)) img.remove();\n  const svg = $('svg');\n  let paths = '';\n  const ov = $('overlay');\n  for (const p of [...ov.querySelectorAll('.pin')]) p.remove();\n  for (const m of list()) {\n    if (m.track.length > 1) {\n      const d = m.track.map((p, i) => (i ? 'L' : 'M') + (wx(p.lon, z) - left).toFixed(1) + ' ' + (wy(p.lat, z) - top).toFixed(1)).join(' ');\n      paths += '<path d=\"' + d + '\" fill=\"none\" stroke=\"' + (m.latest.flags & 1 ? '#dc2626' : '#a78bfa') + '\" stroke-width=\"2\" stroke-opacity=\".7\"/>';\n    }\n    if (!m.pos) continue;\n    const x = wx(m.pos.lon, z) - left, y = wy(m.pos.lat, z) - top;\n    const r = m.pos.acc / (156543.03 * Math.cos(m.pos.lat * Math.PI / 180) / n);\n    if (r > 4) paths += '<circle cx=\"' + x.toFixed(1) + '\" cy=\"' + y.toFixed(1) + '\" r=\"' + r.toFixed(1) + '\" fill=\"#a78bfa\" fill-opacity=\".12\" stroke=\"#a78bfa\" stroke-opacity=\".4\"/>';\n    const pin = document.createElement('div');\n    const old = Date.now() / 1000 - m.latest.sent > 3 * (card.every || 300) + 120;\n    pin.className = 'pin' + (m.latest.flags & 1 ? ' sos' : old ? ' old' : '');\n    pin.style.left = x + 'px'; pin.style.top = y + 'px';\n    pin.textContent = (m.latest.flags & 1 ? '⚠ ' : '') + (m.name || m.id.slice(0, 6));\n    pin.title = ago(m.latest.sent);\n    pin.onclick = () => focusMember(m.id);\n    ov.appendChild(pin);\n  }\n  svg.innerHTML = paths;\n}\n\nfunction render(maybeFit) {\n  const box = $('members');\n  box.innerHTML = '';\n  for (const m of list()) {\n    const r = m.latest;\n    const d = document.createElement('div');\n    d.className = 'card m' + (r.flags & 1 ? ' sos' : '');\n    let html = '<b>' + esc(m.name || m.id.slice(0, 8)) + '</b>';\n    if (r.flags & 1) html += '<span class=\"badge sos\">LOST — SOS</span>';\n    if (r.flags & 2) html += '<span class=\"badge stop\">stopped sharing</span>';\n    html += '<div class=\"muted\">last report ' + ago(r.sent) + (r.battery >= 0 ? ' · battery ' + r.battery + '%' : '') + '</div>';\n    if (m.pos) {\n      html += '<div>' + m.pos.lat.toFixed(5) + ', ' + m.pos.lon.toFixed(5) + ' (±' + m.pos.acc + ' m, ' + ago(m.pos.t) + ')</div>';\n      html += '<div><a target=\"_blank\" rel=\"noopener\" href=\"https://www.openstreetmap.org/?mlat=' + m.pos.lat + '&mlon=' + m.pos.lon + '#map=17/' + m.pos.lat + '/' + m.pos.lon + '\">OpenStreetMap</a> · ' +\n              '<a target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/maps/search/?api=1&query=' + m.pos.lat + ',' + m.pos.lon + '\">Google Maps</a></div>';\n    } else {\n      html += '<div class=\"muted\">no position yet</div>';\n    }\n    d.innerHTML = html;\n    d.onclick = (e) => { if (e.target.tagName !== 'A') focusMember(m.id); };\n    box.appendChild(d);\n  }\n  if (maybeFit && !fitted) fit(); else draw();\n}\n\nfunction focusMember(id) {\n  const m = members.get(id);\n  if (!m || !m.pos) return;\n  view.lat = m.pos.lat; view.lon = m.pos.lon; view.z = Math.max(view.z, 15);\n  draw();\n}\n\n// pan and zoom\n(() => {\n  const el = $('map');\n  let drag = null;\n  el.addEventListener('pointerdown', (e) => { if (e.target.closest('.zoom') || e.target.classList.contains('pin')) return; drag = { x: e.clientX, y: e.clientY, cx: wx(view.lon, view.z), cy: wy(view.lat, view.z) }; el.setPointerCapture(e.pointerId); });\n  el.addEventListener('pointermove', (e) => { if (!drag) return; const cx = drag.cx - (e.clientX - drag.x), cy = drag.cy - (e.clientY - drag.y); view.lon = lonOf(cx, view.z); view.lat = latOf(cy, view.z); draw(); });\n  el.addEventListener('pointerup', () => { drag = null; });\n  el.addEventListener('wheel', (e) => { e.preventDefault(); zoom(e.deltaY < 0 ? 1 : -1); }, { passive: false });\n  $('zin').onclick = () => zoom(1);\n  $('zout').onclick = () => zoom(-1);\n  $('fit').onclick = () => fit();\n  window.addEventListener('resize', draw);\n})();\nfunction zoom(d) { view.z = Math.min(19, Math.max(2, view.z + d)); draw(); }\n\n$('open').onclick = () => card && api('/admin/api/trip').then((st) => useKey($('key').value, st.hash));\n$('forget').onclick = () => { for (const k of Object.keys(sessionStorage)) if (k.startsWith('tripkey:')) sessionStorage.removeItem(k); $('key').value = ''; };\nsetInterval(() => render(false), 30000);\ndraw();\nload();\n</script>\n</body>\n</html>\n";
const TRIPCRYPTO_JS = "// Opens trip location reports in the leader's browser (docs/trip.md): the\n// relay hands over the encrypted packets, the map key never leaves this page.\n// X25519 (RFC 7748), ChaCha20-Poly1305 (RFC 8439), Noise_X_25519_ChaChaPoly_SHA256\n// as the Go core seals them (core/e2e), and the report layout of core/trip.\nconst TripCrypto = (() => {\n  const P = (1n << 255n) - 19n;\n  const md = (a) => { const r = a % P; return r < 0n ? r + P : r; };\n  const le2n = (b) => { let r = 0n; for (let i = b.length - 1; i >= 0; i--) r = (r << 8n) | BigInt(b[i]); return r; };\n  const n2le = (n, len) => { const o = new Uint8Array(len); for (let i = 0; i < len; i++) { o[i] = Number(n & 255n); n >>= 8n; } return o; };\n  function powmod(b, e) {\n    let r = 1n; b = md(b);\n    while (e > 0n) { if (e & 1n) r = md(r * b); b = md(b * b); e >>= 1n; }\n    return r;\n  }\n  function x25519(k, u) {\n    const ks = Uint8Array.from(k); ks[0] &= 248; ks[31] &= 127; ks[31] |= 64;\n    const sc = le2n(ks);\n    const ub = Uint8Array.from(u); ub[31] &= 127;\n    const x1 = md(le2n(ub));\n    let x2 = 1n, z2 = 0n, x3 = x1, z3 = 1n, swap = 0n;\n    for (let t = 254; t >= 0; t--) {\n      const kt = (sc >> BigInt(t)) & 1n;\n      swap ^= kt;\n      if (swap) { [x2, x3] = [x3, x2]; [z2, z3] = [z3, z2]; }\n      swap = kt;\n      const A = md(x2 + z2), AA = md(A * A), B = md(x2 - z2), BB = md(B * B), E = md(AA - BB);\n      const C = md(x3 + z3), D = md(x3 - z3), DA = md(D * A), CB = md(C * B);\n      x3 = md((DA + CB) * (DA + CB));\n      z3 = md(x1 * md((DA - CB) * (DA - CB)));\n      x2 = md(AA * BB);\n      z2 = md(E * md(AA + 121665n * E));\n    }\n    if (swap) { [x2, x3] = [x3, x2]; [z2, z3] = [z3, z2]; }\n    return n2le(md(x2 * powmod(z2, P - 2n)), 32);\n  }\n  const BASE = (() => { const b = new Uint8Array(32); b[0] = 9; return b; })();\n\n  function chachaBlock(key, counter, nonce) {\n    const c = new Uint32Array(16);\n    c[0] = 0x61707865; c[1] = 0x3320646e; c[2] = 0x79622d32; c[3] = 0x6b206574;\n    const kv = new DataView(key.buffer, key.byteOffset, 32);\n    for (let i = 0; i < 8; i++) c[4 + i] = kv.getUint32(i * 4, true);\n    c[12] = counter;\n    const nv = new DataView(nonce.buffer, nonce.byteOffset, 12);\n    for (let i = 0; i < 3; i++) c[13 + i] = nv.getUint32(i * 4, true);\n    const x = c.slice();\n    const rotl = (v, n) => (v << n) | (v >>> (32 - n));\n    const qr = (a, b, cc, d) => {\n      x[a] += x[b]; x[d] = rotl(x[d] ^ x[a], 16);\n      x[cc] += x[d]; x[b] = rotl(x[b] ^ x[cc], 12);\n      x[a] += x[b]; x[d] = rotl(x[d] ^ x[a], 8);\n      x[cc] += x[d]; x[b] = rotl(x[b] ^ x[cc], 7);\n    };\n    for (let i = 0; i < 10; i++) {\n      qr(0, 4, 8, 12); qr(1, 5, 9, 13); qr(2, 6, 10, 14); qr(3, 7, 11, 15);\n      qr(0, 5, 10, 15); qr(1, 6, 11, 12); qr(2, 7, 8, 13); qr(3, 4, 9, 14);\n    }\n    const out = new Uint8Array(64), ov = new DataView(out.buffer);\n    for (let i = 0; i < 16; i++) ov.setUint32(i * 4, (x[i] + c[i]) >>> 0, true);\n    return out;\n  }\n  function poly1305(key, msg) {\n    const r = le2n(key.subarray(0, 16)) & 0x0ffffffc0ffffffc0ffffffc0fffffffn;\n    const s = le2n(key.subarray(16, 32));\n    const p = (1n << 130n) - 5n;\n    let acc = 0n;\n    for (let i = 0; i < msg.length; i += 16) {\n      const blk = msg.subarray(i, Math.min(i + 16, msg.length));\n      acc = ((acc + le2n(blk) + (1n << BigInt(8 * blk.length))) * r) % p;\n    }\n    return n2le((acc + s) & ((1n << 128n) - 1n), 16);\n  }\n  const pad16 = (n) => (16 - (n % 16)) % 16;\n  function aeadOpen(key, nonce, data, aad) {\n    if (data.length < 16) return null;\n    const ct = data.subarray(0, data.length - 16), tag = data.subarray(data.length - 16);\n    const otk = chachaBlock(key, 0, nonce).subarray(0, 32);\n    const mac = new Uint8Array(aad.length + pad16(aad.length) + ct.length + pad16(ct.length) + 16);\n    mac.set(aad, 0);\n    mac.set(ct, aad.length + pad16(aad.length));\n    const lv = new DataView(mac.buffer, mac.length - 16);\n    lv.setUint32(0, aad.length, true); lv.setUint32(8, ct.length, true);\n    const want = poly1305(otk, mac);\n    let diff = 0;\n    for (let i = 0; i < 16; i++) diff |= want[i] ^ tag[i];\n    if (diff !== 0) return null;\n    const pt = new Uint8Array(ct.length);\n    for (let off = 0, ctr = 1; off < ct.length; off += 64, ctr++) {\n      const ks = chachaBlock(key, ctr, nonce);\n      for (let i = 0; i < 64 && off + i < ct.length; i++) pt[off + i] = ct[off + i] ^ ks[i];\n    }\n    return pt;\n  }\n\n  const cat = (...a) => { const o = new Uint8Array(a.reduce((n, x) => n + x.length, 0)); let i = 0; for (const x of a) { o.set(x, i); i += x.length; } return o; };\n  const subtle = globalThis.crypto.subtle;\n  const sha256 = async (b) => new Uint8Array(await subtle.digest('SHA-256', b));\n  async function hmac(key, data) {\n    const k = await subtle.importKey('raw', key, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);\n    return new Uint8Array(await subtle.sign('HMAC', k, data));\n  }\n  async function hkdf2(ck, ikm) {\n    const t = await hmac(ck, ikm);\n    const o1 = await hmac(t, Uint8Array.of(1));\n    const o2 = await hmac(t, cat(o1, Uint8Array.of(2)));\n    return [o1, o2];\n  }\n  const NONCE0 = new Uint8Array(12);\n  const NAME = new TextEncoder().encode('Noise_X_25519_ChaChaPoly_SHA256');\n\n  // openX decrypts a Noise X message to the static key priv/pub.\n  async function openX(priv, pub, prologue, msg) {\n    if (msg.length < 96) return null;\n    let h = new Uint8Array(32); h.set(NAME);\n    let ck = h.slice();\n    h = await sha256(cat(h, prologue));\n    h = await sha256(cat(h, pub));\n    const re = msg.subarray(0, 32);\n    h = await sha256(cat(h, re));\n    let k;\n    [ck, k] = await hkdf2(ck, x25519(priv, re));\n    const encS = msg.subarray(32, 80);\n    const rs = aeadOpen(k, NONCE0, encS, h);\n    if (!rs) return null;\n    h = await sha256(cat(h, encS));\n    [ck, k] = await hkdf2(ck, x25519(priv, rs));\n    const pt = aeadOpen(k, NONCE0, msg.subarray(80), h);\n    if (!pt) return null;\n    return { senderX: rs, payload: pt };\n  }\n\n  const hex = (b) => Array.from(b, (x) => x.toString(16).padStart(2, '0')).join('');\n  const unhex = (s) => { const o = new Uint8Array(s.length / 2); for (let i = 0; i < o.length; i++) o[i] = parseInt(s.substr(i * 2, 2), 16); return o; };\n\n  // openReport opens one raw packet (Uint8Array) for the trip; null if it is\n  // not a report this key opens.\n  async function openReport(priv, pub, raw) {\n    if (raw.length < 26 + 96 + 32 + 5) return null;\n    if ((raw[0] >> 6) !== 1 || ((raw[0] >> 3) & 7) !== 0 || (raw[0] & 4)) return null; // v1 DATA, not fragmented\n    const prologue = cat(Uint8Array.of(raw[0] & 0xf8), raw.subarray(2, 26));\n    const o = await openX(priv, pub, prologue, raw.subarray(26));\n    if (!o || o.payload.length < 32 + 5) return null;\n    const ed = o.payload.subarray(0, 32), inner = o.payload.subarray(32);\n    if (inner[0] !== 10) return null; // e2e.ContentTrip\n    const dv = new DataView(inner.buffer, inner.byteOffset, inner.length);\n    const sent = dv.getUint32(1, false);\n    const c = inner.subarray(5);\n    if (c.length < 16 || c[0] !== 1) return null; // a report\n    const cv = new DataView(c.buffer, c.byteOffset, c.length);\n    const nameLen = c[15];\n    const id = (await sha256(cat(o.senderX, ed))).subarray(0, 16);\n    return {\n      id: hex(raw.subarray(2, 10)), member: hex(id), key: hex(cat(o.senderX, ed)), sent,\n      flags: c[1], lat: cv.getInt32(2, false) / 1e7, lon: cv.getInt32(6, false) / 1e7,\n      accuracy: cv.getUint16(10, false), fixAge: cv.getUint16(12, false),\n      battery: c[14] === 255 ? -1 : c[14],\n      name: new TextDecoder().decode(c.subarray(16, 16 + nameLen)),\n    };\n  }\n\n  return { x25519, BASE, openX, openReport, hex, unhex, aeadOpen, chachaBlock, poly1305 };\n})();\nif (typeof module !== 'undefined') module.exports = TripCrypto;\n";
// ---- src/util.js ----
// Byte helpers and the relay's binary codecs (core/packet frames, core/wire
// gateway and sync bodies). Plain functions: the build joins every module
// into one script, so names are unique across src/.

const TE = new TextEncoder();
const TD = new TextDecoder();

function utf8(s) { return TE.encode(s); }
function fromUtf8(b) { return TD.decode(b); }

function cat(...parts) {
  let n = 0;
  for (const p of parts) n += p.length;
  const out = new Uint8Array(n);
  let i = 0;
  for (const p of parts) { out.set(p, i); i += p.length; }
  return out;
}

function hex(b) {
  let s = '';
  for (let i = 0; i < b.length; i++) s += b[i].toString(16).padStart(2, '0');
  return s;
}

function unhex(s) {
  if (typeof s !== 'string' || s.length % 2 || /[^0-9a-fA-F]/.test(s)) throw new Error('bad hex');
  const out = new Uint8Array(s.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(s.substr(i * 2, 2), 16);
  return out;
}

function b64(b) {
  let s = '';
  for (let i = 0; i < b.length; i += 0x8000) s += String.fromCharCode.apply(null, b.subarray(i, i + 0x8000));
  return btoa(s);
}

function unb64(s) {
  const bin = atob(s);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function b64url(b) { return b64(b).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''); }
function unb64url(s) {
  s = s.replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4) s += '=';
  return unb64(s);
}

function equalBytes(a, b) {
  if (a.length !== b.length) return false;
  let d = 0;
  for (let i = 0; i < a.length; i++) d |= a[i] ^ b[i];
  return d === 0;
}

function randomBytes(n) {
  const b = new Uint8Array(n);
  crypto.getRandomValues(b);
  return b;
}

function u32be(n) { return Uint8Array.of((n >>> 24) & 255, (n >>> 16) & 255, (n >>> 8) & 255, n & 255); }
function readU32be(b, i) { return ((b[i] << 24) | (b[i + 1] << 16) | (b[i + 2] << 8) | b[i + 3]) >>> 0; }

const MAX_PACKET = 64 * 1024;

// Frames: len(4, big-endian) || raw, repeated (core/packet frame.go).
function encodeFrames(raws) {
  return cat(...raws.flatMap((r) => [u32be(r.length), r]));
}

function decodeFrames(b) {
  const out = [];
  let i = 0;
  while (i < b.length) {
    if (b.length - i < 4) throw new Error('short frame');
    const n = readU32be(b, i);
    if (n > MAX_PACKET) throw new Error('frame too large');
    if (b.length - i - 4 < n) throw new Error('short frame');
    out.push(b.slice(i + 4, i + 4 + n));
    i += 4 + n;
  }
  return out;
}

// Gateway body: count(2) || count × dest(16) || frames (core/wire).
function decodeGateway(b) {
  if (b.length < 2) throw new Error('short gateway body');
  const n = (b[0] << 8) | b[1];
  if (b.length < 2 + n * 16) throw new Error('short gateway serve list');
  const serve = [];
  for (let i = 0; i < n; i++) serve.push(hex(b.subarray(2 + i * 16, 18 + i * 16)));
  return { serve, upload: decodeFrames(b.subarray(2 + n * 16)) };
}

// Sync items: frames of region_len(1) || region || raw (core/wire).
function encodeSync(items) {
  return encodeFrames(items.map((it) => {
    const r = utf8(it.region || '').subarray(0, 255);
    return cat(Uint8Array.of(r.length), r, it.raw);
  }));
}

function decodeSync(b) {
  return decodeFrames(b).map((f) => {
    if (f.length < 1 || f.length < 1 + f[0]) throw new Error('bad sync item');
    return { region: fromUtf8(f.subarray(1, 1 + f[0])), raw: f.slice(1 + f[0]) };
  });
}

function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

// ---- src/crypto.js ----
// Crypto for the edge relay: SHA-2 and HMAC from WebCrypto; Ed25519 from
// WebCrypto when the runtime has it, else in JavaScript (BigInt); X25519 and
// ChaCha20-Poly1305 in JavaScript (only the admin panel's login code needs
// them); Noise_X_25519_ChaChaPoly_SHA256 sealing as core/e2e does it.


const subtle = crypto.subtle;

async function sha256(b) { return new Uint8Array(await subtle.digest('SHA-256', b)); }
async function sha512(b) { return new Uint8Array(await subtle.digest('SHA-512', b)); }

async function hmac256(key, data) {
  const k = await subtle.importKey('raw', key, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return new Uint8Array(await subtle.sign('HMAC', k, data));
}

// ---- field arithmetic mod 2^255-19 ----
const P = (1n << 255n) - 19n;
const md = (a) => { const r = a % P; return r < 0n ? r + P : r; };
function powmod(b, e, m = P) {
  let r = 1n;
  b %= m; if (b < 0n) b += m;
  while (e > 0n) { if (e & 1n) r = (r * b) % m; b = (b * b) % m; e >>= 1n; }
  return r;
}
const inv = (a) => powmod(a, P - 2n);
function le2n(b) { let r = 0n; for (let i = b.length - 1; i >= 0; i--) r = (r << 8n) | BigInt(b[i]); return r; }
function n2le(n, len) { const o = new Uint8Array(len); for (let i = 0; i < len; i++) { o[i] = Number(n & 255n); n >>= 8n; } return o; }

// ---- X25519 (RFC 7748) ----
function x25519(k, u) {
  const ks = Uint8Array.from(k); ks[0] &= 248; ks[31] &= 127; ks[31] |= 64;
  const sc = le2n(ks);
  const ub = Uint8Array.from(u); ub[31] &= 127;
  const x1 = md(le2n(ub));
  let x2 = 1n, z2 = 0n, x3 = x1, z3 = 1n, swap = 0n;
  for (let t = 254; t >= 0; t--) {
    const kt = (sc >> BigInt(t)) & 1n;
    swap ^= kt;
    if (swap) { [x2, x3] = [x3, x2]; [z2, z3] = [z3, z2]; }
    swap = kt;
    const A = md(x2 + z2), AA = md(A * A), B = md(x2 - z2), BB = md(B * B), E = md(AA - BB);
    const C = md(x3 + z3), D = md(x3 - z3), DA = md(D * A), CB = md(C * B);
    x3 = md((DA + CB) * (DA + CB));
    z3 = md(x1 * md((DA - CB) * (DA - CB)));
    x2 = md(AA * BB);
    z2 = md(E * md(AA + 121665n * E));
  }
  if (swap) { [x2, x3] = [x3, x2]; [z2, z3] = [z3, z2]; }
  return n2le(md(x2 * inv(z2)), 32);
}
const X25519_BASE = (() => { const b = new Uint8Array(32); b[0] = 9; return b; })();

// ---- ChaCha20-Poly1305 (RFC 8439) ----
function chachaBlock(key, counter, nonce) {
  const c = new Uint32Array(16);
  c[0] = 0x61707865; c[1] = 0x3320646e; c[2] = 0x79622d32; c[3] = 0x6b206574;
  const kv = new DataView(key.buffer, key.byteOffset, 32);
  for (let i = 0; i < 8; i++) c[4 + i] = kv.getUint32(i * 4, true);
  c[12] = counter;
  const nv = new DataView(nonce.buffer, nonce.byteOffset, 12);
  for (let i = 0; i < 3; i++) c[13 + i] = nv.getUint32(i * 4, true);
  const x = c.slice();
  const rotl = (v, n) => (v << n) | (v >>> (32 - n));
  const qr = (a, b, cc, d) => {
    x[a] += x[b]; x[d] = rotl(x[d] ^ x[a], 16);
    x[cc] += x[d]; x[b] = rotl(x[b] ^ x[cc], 12);
    x[a] += x[b]; x[d] = rotl(x[d] ^ x[a], 8);
    x[cc] += x[d]; x[b] = rotl(x[b] ^ x[cc], 7);
  };
  for (let i = 0; i < 10; i++) {
    qr(0, 4, 8, 12); qr(1, 5, 9, 13); qr(2, 6, 10, 14); qr(3, 7, 11, 15);
    qr(0, 5, 10, 15); qr(1, 6, 11, 12); qr(2, 7, 8, 13); qr(3, 4, 9, 14);
  }
  const out = new Uint8Array(64), ov = new DataView(out.buffer);
  for (let i = 0; i < 16; i++) ov.setUint32(i * 4, (x[i] + c[i]) >>> 0, true);
  return out;
}
function chachaXor(key, nonce, data) {
  const out = new Uint8Array(data.length);
  for (let off = 0, ctr = 1; off < data.length; off += 64, ctr++) {
    const ks = chachaBlock(key, ctr, nonce);
    for (let i = 0; i < 64 && off + i < data.length; i++) out[off + i] = data[off + i] ^ ks[i];
  }
  return out;
}
function poly1305(key, msg) {
  const r = le2n(key.subarray(0, 16)) & 0x0ffffffc0ffffffc0ffffffc0fffffffn;
  const s = le2n(key.subarray(16, 32));
  const p = (1n << 130n) - 5n;
  let acc = 0n;
  for (let i = 0; i < msg.length; i += 16) {
    const blk = msg.subarray(i, Math.min(i + 16, msg.length));
    acc = ((acc + le2n(blk) + (1n << BigInt(8 * blk.length))) * r) % p;
  }
  return n2le((acc + s) & ((1n << 128n) - 1n), 16);
}
function macData(aad, ct) {
  const pad = (n) => (16 - (n % 16)) % 16;
  const m = new Uint8Array(aad.length + pad(aad.length) + ct.length + pad(ct.length) + 16);
  m.set(aad, 0);
  m.set(ct, aad.length + pad(aad.length));
  const lv = new DataView(m.buffer, m.length - 16);
  lv.setUint32(0, aad.length, true); lv.setUint32(8, ct.length, true);
  return m;
}
function aeadSeal(key, nonce, pt, aad) {
  const ct = chachaXor(key, nonce, pt);
  const tag = poly1305(chachaBlock(key, 0, nonce).subarray(0, 32), macData(aad, ct));
  return cat(ct, tag);
}
function aeadOpen(key, nonce, data, aad) {
  if (data.length < 16) return null;
  const ct = data.subarray(0, data.length - 16);
  const tag = poly1305(chachaBlock(key, 0, nonce).subarray(0, 32), macData(aad, ct));
  if (!equalBytes(tag, data.subarray(data.length - 16))) return null;
  return chachaXor(key, nonce, ct);
}

// ---- Noise_X_25519_ChaChaPoly_SHA256, initiator (core/e2e Seal, first contact) ----
const NOISE_X = utf8('Noise_X_25519_ChaChaPoly_SHA256');
const NONCE0 = new Uint8Array(12);
async function hkdf2(ck, ikm) {
  const t = await hmac256(ck, ikm);
  const o1 = await hmac256(t, Uint8Array.of(1));
  const o2 = await hmac256(t, cat(o1, Uint8Array.of(2)));
  return [o1, o2];
}

/** Seals payload from the static key (sPriv, sPub) to the recipient's X25519 key rs. */
async function noiseXSeal(sPriv, sPub, rs, prologue, payload) {
  let h = new Uint8Array(32); h.set(NOISE_X);
  let ck = h.slice();
  h = await sha256(cat(h, prologue));
  h = await sha256(cat(h, rs));
  const ePriv = randomBytes(32);
  const ePub = x25519(ePriv, X25519_BASE);
  h = await sha256(cat(h, ePub));
  let k;
  [ck, k] = await hkdf2(ck, x25519(ePriv, rs));
  const encS = aeadSeal(k, NONCE0, sPub, h);
  h = await sha256(cat(h, encS));
  [ck, k] = await hkdf2(ck, x25519(sPriv, rs));
  const ct = aeadSeal(k, NONCE0, payload, h);
  return cat(ePub, encS, ct);
}

/** Opens a Noise X message to (priv, pub); returns {senderX, payload} or null. */
async function noiseXOpen(priv, pub, prologue, msg) {
  if (msg.length < 96) return null;
  let h = new Uint8Array(32); h.set(NOISE_X);
  let ck = h.slice();
  h = await sha256(cat(h, prologue));
  h = await sha256(cat(h, pub));
  const re = msg.subarray(0, 32);
  h = await sha256(cat(h, re));
  let k;
  [ck, k] = await hkdf2(ck, x25519(priv, re));
  const encS = msg.subarray(32, 80);
  const rs = aeadOpen(k, NONCE0, encS, h);
  if (!rs) return null;
  h = await sha256(cat(h, encS));
  [ck, k] = await hkdf2(ck, x25519(priv, rs));
  const pt = aeadOpen(k, NONCE0, msg.subarray(80), h);
  return pt ? { senderX: rs, payload: pt } : null;
}

// ---- Ed25519 (RFC 8032) ----
const L = (1n << 252n) + 27742317777372353535851937790883648493n;
const D = md(-121665n * inv(121666n));
const SQRT_M1 = powmod(2n, (P - 1n) / 4n);
const BY = md(4n * inv(5n));
const BX = recoverX(BY, 0);
const BASE = [BX, BY, 1n, md(BX * BY)];

function recoverX(y, sign) {
  const y2 = md(y * y);
  const x2 = md((y2 - 1n) * inv(D * y2 + 1n));
  if (x2 === 0n) return sign ? null : 0n;
  let x = powmod(x2, (P + 3n) / 8n);
  if (md(x * x - x2) !== 0n) x = md(x * SQRT_M1);
  if (md(x * x - x2) !== 0n) return null;
  if (Number(x & 1n) !== sign) x = P - x;
  return x;
}
function edAdd(p, q) {
  const [X1, Y1, Z1, T1] = p, [X2, Y2, Z2, T2] = q;
  const A = md((Y1 - X1) * (Y2 - X2)), B = md((Y1 + X1) * (Y2 + X2));
  const C = md(2n * D * T1 * T2), Dd = md(2n * Z1 * Z2);
  const E = B - A, F = Dd - C, G = Dd + C, H = B + A;
  return [md(E * F), md(G * H), md(F * G), md(E * H)];
}
function edMul(s, p) {
  let q = [0n, 1n, 1n, 0n];
  for (; s > 0n; s >>= 1n) { if (s & 1n) q = edAdd(q, p); p = edAdd(p, p); }
  return q;
}
function edEncode(p) {
  const zi = inv(p[2]);
  const x = md(p[0] * zi), y = md(p[1] * zi);
  const b = n2le(y, 32);
  b[31] |= Number(x & 1n) << 7;
  return b;
}
function edDecode(b) {
  if (b.length !== 32) return null;
  const c = Uint8Array.from(b);
  const sign = c[31] >> 7; c[31] &= 127;
  const y = le2n(c);
  if (y >= P) return null;
  const x = recoverX(y, sign);
  return x === null ? null : [x, y, 1n, md(x * y)];
}

async function jsVerify(pub, msg, sig) {
  if (sig.length !== 64 || pub.length !== 32) return false;
  const A = edDecode(pub), R = edDecode(sig.subarray(0, 32));
  const S = le2n(sig.subarray(32));
  if (!A || !R || S >= L) return false;
  const k = le2n(await sha512(cat(sig.subarray(0, 32), pub, msg))) % L;
  return equalBytes(edEncode(edMul(S, BASE)), edEncode(edAdd(R, edMul(k, A))));
}

async function jsKeys(seed) {
  const h = await sha512(seed);
  const a = Uint8Array.from(h.subarray(0, 32)); a[0] &= 248; a[31] &= 127; a[31] |= 64;
  const s = le2n(a);
  return { s, prefix: h.subarray(32), pub: edEncode(edMul(s, BASE)) };
}
async function jsSign(seed, msg) {
  const { s, prefix, pub } = await jsKeys(seed);
  const r = le2n(await sha512(cat(prefix, msg))) % L;
  const R = edEncode(edMul(r, BASE));
  const k = le2n(await sha512(cat(R, pub, msg))) % L;
  return cat(R, n2le((r + k * s) % L, 32));
}

// WebCrypto Ed25519 when the runtime has it (fast, native); else JavaScript.
let nativeEd = null; // null: not tested yet
async function hasNativeEd() {
  if (nativeEd !== null) return nativeEd;
  try {
    const k = await subtle.importKey('raw', new Uint8Array(32).fill(1), { name: 'Ed25519' }, false, ['verify']);
    await subtle.verify({ name: 'Ed25519' }, k, new Uint8Array(64), new Uint8Array(1));
    nativeEd = true;
  } catch (e) {
    nativeEd = false;
  }
  return nativeEd;
}
const PKCS8_ED = Uint8Array.of(0x30, 0x2e, 0x02, 0x01, 0x00, 0x30, 0x05, 0x06, 0x03, 0x2b, 0x65, 0x70, 0x04, 0x22, 0x04, 0x20);

async function edVerify(pub, msg, sig) {
  if (await hasNativeEd()) {
    try {
      const k = await subtle.importKey('raw', pub, { name: 'Ed25519' }, false, ['verify']);
      return await subtle.verify({ name: 'Ed25519' }, k, sig, msg);
    } catch (e) {
      return false;
    }
  }
  return jsVerify(pub, msg, sig);
}

async function edSign(seed, msg) {
  if (await hasNativeEd()) {
    try {
      const k = await subtle.importKey('pkcs8', cat(PKCS8_ED, seed), { name: 'Ed25519' }, false, ['sign']);
      return new Uint8Array(await subtle.sign({ name: 'Ed25519' }, k, msg));
    } catch (e) { /* fall through to JavaScript */ }
  }
  return jsSign(seed, msg);
}

async function edPublic(seed) { return (await jsKeys(seed)).pub; }

/** Signature under a domain tag, as identity.SignDomain / Public.Verify. */
function verifyDomain(edPub, domain, msg, sig) { return edVerify(edPub, cat(utf8(domain), msg), sig); }
function signDomain(edSeed, domain, msg) { return edSign(edSeed, cat(utf8(domain), msg)); }

// Exposed for tests: the JavaScript paths regardless of the runtime.
const edJS = { verify: jsVerify, sign: jsSign };

// ---- src/packet.js ----
// Packets as relays see them (docs/protocol.md §2, core/packet, core/announce):
// headers, keys, announces, receipts, mailbox-fetch signatures, proof of work.


const T_DATA = 0, T_RECEIPT = 1, T_ANNOUNCE = 2;
const VERSION = 1;
const HEADER = 26;
const CTX_FRAGMENTED = 4;

/** Parses a raw packet: {type, ctx, id (hex), dest (hex), frag, body} or null. */
function decodePacket(raw) {
  if (raw.length < HEADER || raw.length > MAX_PACKET || raw[0] >> 6 !== VERSION) return null;
  const p = {
    type: (raw[0] >> 3) & 7, ctx: raw[0] & 7,
    idBytes: raw.subarray(2, 10), destBytes: raw.subarray(10, 26),
    frag: 0, body: raw.subarray(HEADER),
  };
  if (p.ctx & CTX_FRAGMENTED) {
    if (p.body.length < 1) return null;
    const idx = p.body[0] >> 4, count = (p.body[0] & 15) + 1;
    if (idx >= count) return null;
    p.frag = idx;
    p.body = p.body.subarray(1);
  }
  p.id = hex(p.idBytes);
  p.dest = hex(p.destBytes);
  return p;
}

/** The packet's store key: id and fragment index. */
function packetKey(p) { return { pid: p.id, frag: p.frag }; }

/** Public identity from X || Ed (64 bytes): {x, ed, hash}. */
async function publicFrom(b) {
  if (b.length !== 64) return null;
  return { x: b.slice(0, 32), ed: b.slice(32, 64), hash: hex((await sha256(b)).subarray(0, 16)) };
}

/** Verifies an announce: {pub, time, name, flags, relay} or null (core/announce Parse). */
async function parseAnnounce(p) {
  if (p.type !== T_ANNOUNCE) return null;
  const b = p.body;
  if (b.length < 64 + 4 + 1 + 64) return null;
  const adLen = b[68];
  if (adLen > 64 || b.length !== 69 + adLen + 64) return null;
  const pub = await publicFrom(b.subarray(0, 64));
  if (!pub || pub.hash !== p.dest) return null;
  const signed = b.subarray(0, 69 + adLen), sig = b.subarray(69 + adLen);
  if (!(await verifyDomain(pub.ed, 'MESHMSG-ANNC', cat(p.destBytes, signed), sig))) return null;
  const a = { pub, time: readU32be(b, 64), name: '', flags: 0, relay: '' };
  let ad = b.subarray(69, 69 + adLen);
  while (ad.length > 0) {
    if (ad.length < 2 || ad.length < 2 + ad[1]) return null;
    const tag = ad[0], val = ad.subarray(2, 2 + ad[1]);
    if (tag === 1) a.name = new TextDecoder().decode(val);
    if (tag === 2 && val.length) a.flags = val[0];
    ad = ad.subarray(2 + ad[1]);
  }
  return a;
}

const FLAG_DELEGATE = 1;

/** The deterministic packet ID of the receipt for acked (hex). */
async function receiptID(ackedHex) {
  return hex((await sha256(cat(utf8('MESHMSG-RCPT-ID'), unhex(ackedHex)))).subarray(0, 8));
}

/** The packet a receipt acknowledges (hex), checking its ID; null if malformed. */
async function receiptAcked(p) {
  if (p.type !== T_RECEIPT || p.body.length !== 8 + 64) return null;
  const acked = hex(p.body.subarray(0, 8));
  return (await receiptID(acked)) === p.id ? acked : null;
}

/** Checks a receipt's signature against the recipient's announced key. */
async function verifyReceipt(p, pub) {
  if (pub.hash !== p.dest) return false;
  return verifyDomain(pub.ed, 'MESHMSG-RCPT', cat(p.body.subarray(0, 8), p.destBytes), p.body.subarray(8));
}

/** Checks a mailbox-fetch signature over nonce || dest. */
function verifyFetch(pub, nonce, sig) {
  return verifyDomain(pub.ed, 'MESHMSG-FETCH', cat(utf8(nonce), unhex(pub.hash)), sig);
}

/** Proof of work: SHA-256("MESHMSG-POW" || body || nonce(8, BE)) has need leading zero bits. */
async function checkPoW(body, nonceStr, need) {
  if (need <= 0) return true;
  if (!/^\d{1,20}$/.test(nonceStr || '')) return false;
  let n = BigInt(nonceStr);
  if (n >= 1n << 64n) return false;
  const nb = new Uint8Array(8);
  for (let i = 7; i >= 0; i--) { nb[i] = Number(n & 255n); n >>= 8n; }
  const d = await sha256(cat(utf8('MESHMSG-POW'), body, nb));
  let bits = 0;
  for (const byte of d) {
    if (byte === 0) { bits += 8; continue; }
    bits += Math.clz32(byte) - 24;
    break;
  }
  return bits >= need;
}

/** Builds a raw DATA packet (one frame, not fragmented). */
function buildData(idBytes, destBytes, body, priority, maxHops = 8) {
  const flags = (VERSION << 6) | (T_DATA << 3) | (priority ? 1 : 0);
  return cat(Uint8Array.of(flags, maxHops & 15), idBytes, destBytes, body);
}

/** The Noise prologue of a DATA packet: flags & 0xF8 || id || dest. */
function dataPrologue(idBytes, destBytes) {
  return cat(Uint8Array.of((VERSION << 6) | (T_DATA << 3)), idBytes, destBytes);
}

// ---- src/store-d1.js ----
// The relay's store on Cloudflare D1 (SQLite), the same table as the Go
// relay's (core/store/sqlite.go) with hex and base64 text instead of blobs,
// plus a small key-value table (identity, settings, codes, sessions, trip).


const D1_SCHEMA = [
  `CREATE TABLE IF NOT EXISTS items (
    seq INTEGER PRIMARY KEY AUTOINCREMENT, pid TEXT NOT NULL, frag INTEGER NOT NULL, type INTEGER NOT NULL,
    dest TEXT NOT NULL, raw TEXT NOT NULL, origin TEXT NOT NULL DEFAULT '', region TEXT NOT NULL DEFAULT '',
    received INTEGER NOT NULL, expires INTEGER NOT NULL, UNIQUE(pid, frag))`,
  `CREATE INDEX IF NOT EXISTS items_dest ON items(dest, type, seq)`,
  `CREATE INDEX IF NOT EXISTS items_expires ON items(expires)`,
  `CREATE TABLE IF NOT EXISTS kv (k TEXT PRIMARY KEY, v TEXT NOT NULL, expires INTEGER NOT NULL DEFAULT 0)`,
];

function d1Item(r) {
  return {
    seq: r.seq, pid: r.pid, frag: r.frag, type: r.type, dest: r.dest, raw: unb64(r.raw),
    origin: r.origin, region: r.region, received: r.received, expires: r.expires,
  };
}

class D1Store {
  constructor(db) { this.db = db; this.ready = null; }

  init() {
    if (!this.ready) this.ready = this.db.batch(D1_SCHEMA.map((s) => this.db.prepare(s))).catch((e) => { this.ready = null; throw e; });
    return this.ready;
  }

  async q(sql, ...args) { await this.init(); return (await this.db.prepare(sql).bind(...args).all()).results || []; }

  async put(it) {
    await this.init();
    const ins = this.db.prepare(
      'INSERT OR IGNORE INTO items(pid,frag,type,dest,raw,origin,region,received,expires) VALUES(?,?,?,?,?,?,?,?,?)',
    ).bind(it.pid, it.frag, it.type, it.dest, b64(it.raw), it.origin || '', it.region || '', it.received, it.expires);
    if (it.type === 2) { // the newest announce replaces the older ones of its destination
      const del = this.db.prepare('DELETE FROM items WHERE type=2 AND dest=? AND NOT (pid=? AND frag=?)').bind(it.dest, it.pid, it.frag);
      const res = await this.db.batch([ins, del]);
      return { added: (res[0].meta && res[0].meta.changes) > 0 };
    }
    const res = await ins.run();
    return { added: (res.meta && res.meta.changes) > 0 };
  }

  async has(pid, frag) { return (await this.q('SELECT 1 AS one FROM items WHERE pid=? AND frag=?', pid, frag)).length > 0; }

  async get(pid, frag) {
    const r = await this.q('SELECT * FROM items WHERE pid=? AND frag=?', pid, frag);
    return r.length ? d1Item(r[0]) : null;
  }

  async byDest(dest, after, limit) {
    const rows = await this.q('SELECT * FROM items WHERE dest=? AND type=0 AND seq > ? ORDER BY seq LIMIT ?', dest, after, limit);
    const items = rows.map(d1Item);
    return { items, cursor: items.length ? items[items.length - 1].seq : after };
  }

  /**
   * Items after cursor in order, at most limit looked at; filter
   * {excludeOrigin, types} drops some. cursor passes the dropped ones too.
   */
  async scan(after, limit, filter = {}) {
    const rows = await this.q('SELECT * FROM items WHERE seq > ? ORDER BY seq LIMIT ?', after, limit + 1);
    const more = rows.length > limit;
    const seen = rows.slice(0, limit);
    const items = seen.filter((r) => (!filter.excludeOrigin || r.origin !== filter.excludeOrigin) &&
      (!filter.types || filter.types.includes(r.type))).map(d1Item);
    return { items, cursor: seen.length ? seen[seen.length - 1].seq : after, more };
  }

  async latestAnnounce(dest) {
    const r = await this.q('SELECT * FROM items WHERE dest=? AND type=2 ORDER BY seq DESC LIMIT 1', dest);
    return r.length ? d1Item(r[0]) : null;
  }

  async deleteData(pid) {
    await this.init();
    const res = await this.db.prepare('DELETE FROM items WHERE pid=? AND type=0').bind(pid).run();
    return (res.meta && res.meta.changes) || 0;
  }

  async expire(now) {
    await this.init();
    const res = await this.db.batch([
      this.db.prepare('DELETE FROM items WHERE expires != 0 AND expires < ?').bind(now),
      this.db.prepare('DELETE FROM kv WHERE expires != 0 AND expires < ?').bind(now),
    ]);
    return (res[0].meta && res[0].meta.changes) || 0;
  }

  async count() {
    const r = await this.q('SELECT type, COUNT(*) AS n FROM items GROUP BY type');
    const out = { total: 0, data: 0, receipts: 0, announces: 0 };
    for (const x of r) {
      out.total += x.n;
      if (x.type === 0) out.data = x.n;
      if (x.type === 1) out.receipts = x.n;
      if (x.type === 2) out.announces = x.n;
    }
    return out;
  }

  async kvGet(k) {
    const r = await this.q('SELECT v, expires FROM kv WHERE k=?', k);
    if (!r.length || (r[0].expires && r[0].expires < Date.now())) return null;
    return r[0].v;
  }

  async kvPut(k, v, ttlMs = 0) {
    await this.init();
    await this.db.prepare('INSERT INTO kv(k,v,expires) VALUES(?,?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v, expires=excluded.expires')
      .bind(k, v, ttlMs ? Date.now() + ttlMs : 0).run();
  }

  async kvDel(k) { await this.init(); await this.db.prepare('DELETE FROM kv WHERE k=?').bind(k).run(); }

  /** Stores v under k unless k exists; returns the value now stored. */
  async kvPutIfAbsent(k, v) {
    await this.init();
    await this.db.prepare('INSERT OR IGNORE INTO kv(k,v,expires) VALUES(?,?,0)').bind(k, v).run();
    return this.kvGet(k);
  }
}

// ---- src/store-s3.js ----
// The relay's store in an S3-compatible bucket (Arvan Object Storage), for
// edge platforms without a database. Every packet is one object; its
// metadata is in the object's name, so listings answer most queries
// without reading objects:
//
//   i/<seq>_<type>_<pid>_<frag>_<dest>_<origin tag>   the packet (JSON: raw, origin, region, received, expires)
//   k/<pid>_<frag>                                    → the i/ name (duplicates, receipts, purges)
//   d/<dest>/<seq>                                    → the i/ name (mailboxes; DATA only)
//   a/<dest>                                          → the i/ name of the newest announce
//   kv/<key>                                          small values (identity, settings, codes, trip)
//
// seq is the time in microseconds (16 digits) plus a random part: objects
// written at the same moment from different edge locations get distinct,
// almost ordered numbers. Readers only look at objects older than a few
// seconds (SETTLE), so a slightly late writer is not skipped by a cursor.


const SETTLE_MS = 4000;
const S3_PAGE = 1000;

async function sha256hex(b) { return hex(await sha256(typeof b === 'string' ? utf8(b) : b)); }

function pad16(n) { return String(n).padStart(16, '0'); }

async function originTag(origin) { return (await sha256hex(origin || '')).slice(0, 12); }

function parseItemName(name) {
  // i/<seq>_<type>_<pid>_<frag>_<dest>_<tag>
  const m = /^i\/(\d{16})_(\d)_([0-9a-f]{16})_(\d{1,2})_([0-9a-f]{32})_([0-9a-f]{12})$/.exec(name);
  if (!m) return null;
  return { name, seq: Number(m[1]), type: Number(m[2]), pid: m[3], frag: Number(m[4]), dest: m[5], tag: m[6] };
}

class S3Store {
  /** cfg: {endpoint: "https://s3.ir-thr-at1.arvanstorage.ir", region, bucket, accessKey, secretKey} */
  constructor(cfg) { this.cfg = cfg; }

  async init() {}

  // ---- S3 requests, signed with AWS Signature Version 4 ----
  async s3(method, key, { query = {}, body = null, headers = {} } = {}) {
    const c = this.cfg;
    const base = new URL(c.endpoint.replace(/\/+$/, ''));
    const path = '/' + c.bucket + (key ? '/' + key.split('/').map(encodeURIComponent).join('/') : '');
    const now = new Date();
    const amzDate = now.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
    const day = amzDate.slice(0, 8);
    const payload = body === null ? new Uint8Array(0) : (typeof body === 'string' ? utf8(body) : body);
    const payloadHash = await sha256hex(payload);
    const qs = Object.keys(query).sort().map((k) => `${encodeURIComponent(k)}=${encodeURIComponent(query[k])}`).join('&');
    const h = { host: base.host, 'x-amz-content-sha256': payloadHash, 'x-amz-date': amzDate };
    for (const [hk, hv] of Object.entries(headers)) h[hk.toLowerCase()] = hv;
    const names = Object.keys(h).sort();
    const canonHeaders = names.map((k) => `${k}:${String(h[k]).trim()}\n`).join('');
    const signed = names.join(';');
    const canonical = [method, path, qs, canonHeaders, signed, payloadHash].join('\n');
    const region = c.region || 'us-east-1';
    const scope = `${day}/${region}/s3/aws4_request`;
    const toSign = ['AWS4-HMAC-SHA256', amzDate, scope, await sha256hex(canonical)].join('\n');
    let k = await hmac256(utf8('AWS4' + c.secretKey), utf8(day));
    k = await hmac256(k, utf8(region));
    k = await hmac256(k, utf8('s3'));
    k = await hmac256(k, utf8('aws4_request'));
    const sig = hex(await hmac256(k, utf8(toSign)));
    const auth = `AWS4-HMAC-SHA256 Credential=${c.accessKey}/${scope}, SignedHeaders=${signed}, Signature=${sig}`;
    const hdrs = { ...h, authorization: auth };
    delete hdrs.host;
    const res = await fetch(base.origin + path + (qs ? '?' + qs : ''), { method, headers: hdrs, body: body === null ? undefined : payload });
    return res;
  }

  async getText(key) {
    const r = await this.s3('GET', key);
    if (r.status === 404) return null;
    if (!r.ok) throw new Error(`s3 GET ${key}: ${r.status}`);
    return r.text();
  }

  async putText(key, text) {
    const r = await this.s3('PUT', key, { body: text, headers: { 'content-type': 'application/octet-stream' } });
    if (!r.ok) throw new Error(`s3 PUT ${key}: ${r.status}`);
  }

  async del(key) {
    const r = await this.s3('DELETE', key);
    if (!r.ok && r.status !== 404) throw new Error(`s3 DELETE ${key}: ${r.status}`);
  }

  /** Object names under prefix after startAfter, in order. */
  async list(prefix, startAfter, max) {
    const query = { 'list-type': '2', prefix, 'max-keys': String(Math.min(max, S3_PAGE)) };
    if (startAfter) query['start-after'] = startAfter;
    const r = await this.s3('GET', '', { query });
    if (!r.ok) throw new Error(`s3 LIST ${prefix}: ${r.status}`);
    const xml = await r.text();
    const keys = [...xml.matchAll(/<Key>([^<]*)<\/Key>/g)].map((m) => m[1].replace(/&amp;/g, '&'));
    return { keys, truncated: /<IsTruncated>true<\/IsTruncated>/.test(xml) };
  }

  async readItem(meta) {
    const t = await this.getText(meta.name);
    if (t === null) return null;
    const o = JSON.parse(t);
    return { ...meta, raw: unb64(o.raw), origin: o.origin, region: o.region, received: o.received, expires: o.expires };
  }

  // ---- the store interface (see store-d1.js) ----
  async put(it) {
    if (await this.has(it.pid, it.frag)) return { added: false };
    const seq = Date.now() * 1000 + Math.floor(Math.random() * 1000);
    const name = `i/${pad16(seq)}_${it.type}_${it.pid}_${it.frag}_${it.dest}_${await originTag(it.origin)}`;
    await this.putText(name, JSON.stringify({ raw: b64(it.raw), origin: it.origin || '', region: it.region || '', received: it.received, expires: it.expires }));
    await this.putText(`k/${it.pid}_${it.frag}`, name);
    if (it.type === 0) await this.putText(`d/${it.dest}/${pad16(seq)}`, name);
    if (it.type === 2) {
      const old = await this.getText(`a/${it.dest}`);
      await this.putText(`a/${it.dest}`, name);
      if (old && old !== name) await this.dropItem(parseItemName(old));
    }
    return { added: true };
  }

  async dropItem(m) {
    if (!m) return;
    await this.del(m.name);
    await this.del(`k/${m.pid}_${m.frag}`);
    if (m.type === 0) await this.del(`d/${m.dest}/${pad16(m.seq)}`);
  }

  async has(pid, frag) { return (await this.getText(`k/${pid}_${frag}`)) !== null; }

  async get(pid, frag) {
    const name = await this.getText(`k/${pid}_${frag}`);
    const m = name && parseItemName(name);
    return m ? this.readItem(m) : null;
  }

  settled() { return (Date.now() - SETTLE_MS) * 1000; }

  async byDest(dest, after, limit) {
    const { keys } = await this.list(`d/${dest}/`, after ? `d/${dest}/${pad16(after)}` : '', limit);
    const cutoff = this.settled();
    const out = [];
    let cursor = after;
    for (const k of keys) {
      const seq = Number(k.slice(k.lastIndexOf('/') + 1));
      if (seq > cutoff) break;
      const name = await this.getText(k);
      const m = name && parseItemName(name);
      const it = m && (await this.readItem(m));
      if (it) out.push(it);
      cursor = seq;
    }
    return { items: out, cursor };
  }

  /** As D1Store.scan: names carry type and origin tag, so dropped items are never read. */
  async scan(after, limit, filter = {}) {
    const { keys, truncated } = await this.list('i/', after ? `i/${pad16(after)}` : '', limit + 1);
    const cutoff = this.settled();
    const tag = filter.excludeOrigin ? await originTag(filter.excludeOrigin) : null;
    const seen = [];
    for (const k of keys) {
      const m = parseItemName(k);
      if (!m) continue;
      if (m.seq > cutoff || seen.length >= limit) break;
      seen.push(m);
    }
    const keep = seen.filter((m) => (!tag || m.tag !== tag) && (!filter.types || filter.types.includes(m.type)));
    const items = (await Promise.all(keep.map((m) => this.readItem(m)))).filter(Boolean);
    const cursor = seen.length ? seen[seen.length - 1].seq : after;
    return { items, cursor, more: seen.length >= limit && (truncated || keys.length > limit) };
  }

  async latestAnnounce(dest) {
    const name = await this.getText(`a/${dest}`);
    const m = name && parseItemName(name);
    return m ? this.readItem(m) : null;
  }

  async deleteData(pid) {
    const { keys } = await this.list(`k/${pid}_`, '', 32);
    let n = 0;
    for (const k of keys) {
      const name = await this.getText(k);
      const m = name && parseItemName(name);
      if (m && m.type === 0) { await this.dropItem(m); n++; }
    }
    return n;
  }

  async expire(now) {
    // Objects are named in time order: drop from the oldest while expired.
    let n = 0, after = '';
    for (let page = 0; page < 5; page++) {
      const { keys, truncated } = await this.list('i/', after, 200);
      for (const k of keys) {
        const m = parseItemName(k);
        after = k;
        if (!m) continue;
        const it = await this.readItem(m);
        if (!it) continue;
        if (it.expires && it.expires < now) {
          if (m.type === 2 && (await this.getText(`a/${m.dest}`)) === m.name) await this.del(`a/${m.dest}`);
          await this.dropItem(m);
          n++;
        } else if (Math.floor(m.seq / 1000) > now) {
          return n;
        }
      }
      if (!truncated) break;
    }
    return n;
  }

  async count() { return { total: -1, data: -1, receipts: -1, announces: -1 }; }

  async kvGet(k) {
    const t = await this.getText(`kv/${k}`);
    if (t === null) return null;
    const o = JSON.parse(t);
    if (o.expires && o.expires < Date.now()) return null;
    return o.v;
  }

  async kvPut(k, v, ttlMs = 0) { await this.putText(`kv/${k}`, JSON.stringify({ v, expires: ttlMs ? Date.now() + ttlMs : 0 })); }

  async kvDel(k) { await this.del(`kv/${k}`); }

  async kvPutIfAbsent(k, v) {
    const cur = await this.kvGet(k);
    if (cur !== null) return cur;
    await this.kvPut(k, v);
    return this.kvGet(k);
  }
}

// ---- src/relay.js ----
// The relay's logic (server/relay in Go): an untrusted store-and-forward
// mailbox that federates with other relays and serves gateways.


const CHALLENGE_TTL = 5 * 60 * 1000;
const CARRIER_MIN_AGE = 10 * 60 * 1000;

class Relay {
  /** store: D1Store | S3Store; opts: {name, region, ttlMs: () => number} */
  constructor(store, opts) {
    this.store = store;
    this.opts = opts;
    this.annCache = new Map(); // per request: dest → {a, item} | null
  }

  async announceFor(dest) {
    if (this.annCache.has(dest)) return this.annCache.get(dest);
    const item = await this.store.latestAnnounce(dest);
    let out = null;
    if (item) {
      const p = decodePacket(item.raw);
      const a = p && (await parseAnnounce(p));
      if (a) out = { a, item };
    }
    this.annCache.set(dest, out);
    return out;
  }

  async publicFor(dest) { const r = await this.announceFor(dest); return r ? r.a.pub : null; }

  async delegated(dest) { const r = await this.announceFor(dest); return !!(r && r.a.flags & FLAG_DELEGATE); }

  /** Ingests raw packets; returns how many were new. */
  async ingest(raws, origin, region) {
    const now = Date.now();
    let n = 0;
    for (const raw of raws) if ((await this.ingestOne(raw, origin, region, now)) === 'accepted') n++;
    return n;
  }

  async ingestOne(raw, origin, region, now) {
    const p = decodePacket(raw);
    if (!p) return 'rejected';
    const key = packetKey(p);
    if (await this.store.has(key.pid, key.frag)) return 'duplicate';
    const item = {
      ...key, type: p.type, dest: p.dest, raw, origin, region: '', received: now, expires: now + this.opts.ttlMs(),
    };
    switch (p.type) {
      case T_ANNOUNCE: {
        const a = await parseAnnounce(p);
        if (!a) return 'rejected';
        const old = await this.announceFor(p.dest);
        if (old) {
          if (a.time <= old.a.time) return 'duplicate'; // keep only newer announces
          if (!region) region = old.item.region;
        }
        item.region = region || '';
        this.annCache.delete(p.dest);
        break;
      }
      case T_RECEIPT: {
        const acked = await receiptAcked(p);
        if (!acked) return 'rejected';
        const pub = await this.publicFor(p.dest);
        if (pub) {
          if (!(await verifyReceipt(p, pub))) return 'rejected';
          await this.store.deleteData(acked);
        }
        break;
      }
      case T_DATA:
        if (await this.store.has(await receiptID(p.id), 0)) return 'duplicate'; // already delivered
        break;
      default:
        return 'rejected'; // hop-local types never reach relays
    }
    const { added } = await this.store.put(item);
    return added ? 'accepted' : 'duplicate';
  }

  /** Federation / bridge items: keep the home region each one carries. */
  async ingestSync(items, origin) {
    const now = Date.now();
    let n = 0;
    for (const it of items) if ((await this.ingestOne(it.raw, origin, it.region, now)) === 'accepted') n++;
    return n;
  }

  // Mailbox challenges are stateless (no store write per fetch): the nonce
  // carries its time and an HMAC with the relay's secret, and is good for 5
  // minutes.
  async challengeKey() {
    if (!this.chKey) this.chKey = unhex(await this.store.kvPutIfAbsent('challenge-key', hex(randomBytes(32))));
    return this.chKey;
  }

  async newChallenge() {
    const ts = Math.floor(Date.now() / 1000).toString(16).padStart(10, '0');
    const r = hex(randomBytes(8));
    const mac = hex((await hmac256(await this.challengeKey(), utf8(ts + r))).subarray(0, 12));
    return ts + r + mac;
  }

  async authorizeFetch(dest, nonce, sig) {
    if (await this.delegated(dest)) return true;
    if (!/^[0-9a-f]{50}$/.test(nonce || '')) return false;
    const ts = nonce.slice(0, 10), r = nonce.slice(10, 26), mac = nonce.slice(26);
    const want = hex((await hmac256(await this.challengeKey(), utf8(ts + r))).subarray(0, 12));
    if (want !== mac || Date.now() - parseInt(ts, 16) * 1000 > CHALLENGE_TTL) return false;
    const pub = await this.publicFor(dest);
    return !!pub && sig.length === 64 && verifyFetch(pub, nonce, sig);
  }

  async mailbox(dest, after, limit) {
    const { items, cursor } = await this.store.byDest(dest, after, limit);
    return { raws: items.map((i) => i.raw), cursor };
  }

  async receipts(ids) {
    const out = [];
    for (const id of ids) {
      const it = await this.store.get(await receiptID(id), 0);
      if (it) out.push(it.raw);
    }
    return out;
  }

  /** Everything after cursor not from excludeOrigin (federation / bridges). */
  async pull(after, limit, excludeOrigin) {
    const { items, cursor, more } = await this.store.scan(after, limit, { excludeOrigin });
    return { items: items.map((i) => ({ raw: i.raw, region: i.region })), cursor, more };
  }

  /**
   * Packets for a gateway: receipts, DATA for served destinations that
   * delegated fetching, and (carrier) undelivered DATA of this region.
   */
  async gateway(req) {
    const serve = new Set();
    for (const h of req.serve) if (await this.delegated(h)) serve.add(h);
    const { items, cursor } = await this.store.scan(req.after, 500, { excludeOrigin: req.origin, types: [T_DATA, T_RECEIPT] });
    const now = Date.now();
    const out = [];
    let cur = req.after;
    let quota = req.quota;
    for (const it of items) {
      if (out.length >= req.limit) return { raws: out, cursor: cur };
      let include = false;
      if (it.type === T_RECEIPT || serve.has(it.dest)) {
        include = true;
      } else if (req.carrier && it.type === T_DATA) {
        const ann = await this.announceFor(it.dest);
        const home = ann ? ann.item.region : '';
        if (!(ann && home && home !== this.opts.region)) {
          // Online recipients fetch directly first; stop at the quota (retried next call).
          if (now - it.received < CARRIER_MIN_AGE || quota < it.raw.length) return { raws: out, cursor: cur };
          include = true;
          quota -= it.raw.length;
        }
      }
      if (include) out.push(it.raw);
      cur = it.seq;
    }
    return { raws: out, cursor };
  }

  expire() { return this.store.expire(Date.now()); }
}


// ---- src/trips.js ----
// The relay's trip (docs/trip.md), as server/trips does it: one signed trip
// card at GET /v1/trip, set and ended by the relay's admins who lead it.


/** The exact text of a top-level JSON member's value (the signed card bytes). */
function jsonMemberText(text, member) {
  let i = text.indexOf('{');
  if (i < 0) return null;
  i++;
  const skipWs = () => { while (i < text.length && /\s/.test(text[i])) i++; };
  const readString = () => {
    const start = i++;
    while (i < text.length && text[i] !== '"') i += text[i] === '\\' ? 2 : 1;
    i++;
    return JSON.parse(text.slice(start, i));
  };
  const skipValue = () => {
    skipWs();
    const start = i;
    if (text[i] === '"') { readString(); return text.slice(start, i); }
    if (text[i] === '{' || text[i] === '[') {
      let depth = 0;
      while (i < text.length) {
        const ch = text[i];
        if (ch === '"') { readString(); continue; }
        if (ch === '{' || ch === '[') depth++;
        if (ch === '}' || ch === ']') { depth--; if (depth === 0) { i++; break; } }
        i++;
      }
      return text.slice(start, i);
    }
    while (i < text.length && !/[,}\s]/.test(text[i])) i++;
    return text.slice(start, i);
  };
  for (;;) {
    skipWs();
    if (text[i] !== '"') return null;
    const name = readString();
    skipWs();
    if (text[i++] !== ':') return null;
    const v = skipValue();
    if (name === member) return v;
    skipWs();
    if (text[i] === ',') { i++; continue; }
    return null;
  }
}

/** Verifies a signed trip card (core/trip Signed.Open); returns {card, hash} or throws. */
async function openTripCard(text) {
  const o = JSON.parse(text);
  const cardText = jsonMemberText(text, 'card');
  if (!cardText || typeof o.sig !== 'string') throw new Error('trip: not a signed card');
  const c = JSON.parse(cardText);
  const now = Date.now() / 1000;
  const nameBytes = utf8(c.name || '').length;
  if (c.v !== 1) throw new Error('trip: unknown card version');
  if (!String(c.name || '').trim() || nameBytes > 64) throw new Error('trip: name must be 1–64 bytes');
  if (!Array.isArray(c.leaders) || c.leaders.length < 1 || c.leaders.length > 16) throw new Error('trip: 1–16 leaders');
  if (!(c.every >= 60 && c.every <= 3600)) throw new Error('trip: report interval must be 60–3600 s');
  if (!(c.ends > c.made && c.ends - c.made <= 90 * 86400)) throw new Error('trip: must end after it starts, within 90 days');
  const seen = new Set();
  for (const l of c.leaders) {
    const id = String(l.id || '').toLowerCase();
    if (!/^[0-9a-f]{32}$/.test(id) || seen.has(id) || utf8(l.name || '').length > 64) throw new Error('trip: bad or repeated leader id');
    seen.add(id);
  }
  if (!/^[0-9a-f]{128}$/.test(c.key || '')) throw new Error('trip: key');
  const pub = await publicFrom(unhex(c.key));
  if (!(await verifyDomain(pub.ed, 'mesh-msg trip v1', utf8(cardText), unhex(o.sig)))) throw new Error('trip: bad card signature');
  return { card: c, hash: pub.hash, ended: now >= c.ends };
}

/** Checks the account signature of a trip request; returns the account hash or null. */
async function tripSigner(request, domain, what) {
  try {
    const pk = unhex(request.headers.get('X-Account') || '');
    const sig = unhex(request.headers.get('X-Signature') || '');
    const day = Number(request.headers.get('X-Day'));
    const today = Math.floor(Date.now() / 86400000);
    if (!Number.isInteger(day) || day + 1 < today || day > today + 1) return null;
    const pub = await publicFrom(pk);
    if (!pub || !(await verifyDomain(pub.ed, domain, cat(u32be(day), what), sig))) return null;
    return pub.hash;
  } catch (e) {
    return null;
  }
}

async function currentTrip(ctx) {
  const t = await ctx.store.kvGet('trip');
  if (!t) return null;
  try {
    const r = await openTripCard(t);
    return r.ended ? null : { ...r, text: t };
  } catch (e) {
    return null;
  }
}

function tripText(status, body) { return new Response(body, { status, headers: { 'Content-Type': 'text/plain; charset=utf-8' } }); }

async function tripGet(ctx) {
  const t = await currentTrip(ctx);
  if (!t) return tripText(404, 'no trip on this relay\n');
  return new Response(t.text, { headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-cache' } });
}

async function tripPut(ctx, request) {
  const body = new Uint8Array(await request.arrayBuffer());
  if (body.length > 32 << 10) return tripText(400, 'bad body');
  const text = fromUtf8(body);
  let r;
  try { r = await openTripCard(text); } catch (e) { return tripText(400, e.message); }
  const acct = await tripSigner(request, 'MESHMSG-TRIP-PUT', await sha256(body));
  if (!acct) return tripText(401, 'signed request required');
  const admins = await ctx.admins();
  if (!admins.includes(acct)) return tripText(403, "only this relay's admins can run a trip on it");
  const c = r.card;
  if (r.ended) return tripText(400, 'this trip has already ended');
  if (c.made > Date.now() / 1000 + 86400) return tripText(400, 'the card is dated in the future');
  if (!c.leaders.some((l) => l.id.toLowerCase() === acct)) return tripText(403, "you are not one of this trip's leaders");
  for (const l of c.leaders) {
    if (!admins.includes(l.id.toLowerCase())) {
      return tripText(403, `every leader must be an admin of this relay; ${l.name || l.id} is not (add them in the relay's admin panel)`);
    }
  }
  const cur = await currentTrip(ctx);
  if (cur && cur.card.key === c.key && c.made <= cur.card.made) return tripText(409, 'the relay has a newer card of this trip');
  await ctx.store.kvPut('trip', text);
  return new Response(null, { status: 204 });
}

async function tripDelete(ctx, request, url) {
  const h = (url.searchParams.get('trip') || '').toLowerCase();
  if (!/^[0-9a-f]{32}$/.test(h)) return tripText(400, 'trip= required');
  const acct = await tripSigner(request, 'MESHMSG-TRIP-DEL', unhex(h));
  if (!acct) return tripText(401, 'signed request required');
  if (!(await ctx.admins()).includes(acct)) return tripText(403, "only this relay's admins can end its trip");
  const cur = await currentTrip(ctx);
  if (!cur || cur.hash !== h) return tripText(404, 'this trip is not on the relay');
  await ctx.store.kvDel('trip');
  return new Response(null, { status: 204 });
}

/** The admin panel's view of the trip (server/trips PanelState). */
async function tripPanelState(ctx) {
  const t = await currentTrip(ctx);
  if (!t) return {};
  const admins = await ctx.admins();
  return {
    card: t.card, hash: t.hash, signed: JSON.parse(t.text), link: 'meshtrip:' + b64url(utf8(t.text)),
    leaders: t.card.leaders.map((l) => ({ ...l, admin: admins.includes(l.id.toLowerCase()) })),
  };
}


// ---- src/admin.js ----
// The admin panel at /admin (server/admin in Go, the same page): admins log
// in with a one-time code the relay sends to their Mava account as an
// end-to-end encrypted message. Sessions, codes and settings live in the
// store's key-value table, since edge instances share no memory.


// The network owner's account: an admin of every relay built from this code
// (server/admin.OwnerID).
const OWNER_ID = 'ad2107c8e944bf2a99b3f0cdb2c40903';
const COOKIE = 'mava_admin';
const SESSION_TTL = 12 * 3600 * 1000;
const CODE_TTL = 10 * 60 * 1000;

function adminJSON(status, v, headers = {}) {
  return new Response(JSON.stringify(v), { status, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...headers } });
}
const adminFail = (status, msg) => adminJSON(status, { error: msg });

function parseAccountID(s) {
  const id = String(s || '').trim().toLowerCase();
  if (!/^[0-9a-f]{32}$/.test(id)) throw new Error('An account id is 32 hex characters (Mava → Me).');
  return id;
}

function cookieOf(request, name) {
  for (const part of (request.headers.get('Cookie') || '').split(';')) {
    const [k, ...v] = part.trim().split('=');
    if (k === name) return v.join('=');
  }
  return '';
}

async function sessionOf(ctx, request) {
  const tok = cookieOf(request, COOKIE);
  if (!/^[0-9a-f]{64}$/.test(tok)) return null;
  const id = await ctx.store.kvGet('session:' + tok);
  return id && (await ctx.admins()).includes(id) ? id : null;
}

const PAGE_HEADERS = {
  'Content-Type': 'text/html; charset=utf-8',
  'X-Frame-Options': 'DENY',
  'Cache-Control': 'no-store',
};

/** Routes /admin…; null if the path isn't the panel's. */
async function adminRoute(ctx, request, url) {
  const path = url.pathname;
  const method = request.method;
  if (method === 'GET' && (path === '/admin' || path === '/admin/')) {
    return new Response(PANEL_HTML, { headers: { ...PAGE_HEADERS, 'Referrer-Policy': 'no-referrer',
      'Content-Security-Policy': "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; img-src data:; base-uri 'none'; form-action 'none'; frame-ancestors 'none'" } });
  }
  if (method === 'GET' && path === '/admin/trip') {
    return new Response(TRIPMAP_HTML.replace('/*TRIPCRYPTO*/', TRIPCRYPTO_JS), { headers: { ...PAGE_HEADERS, 'Referrer-Policy': 'strict-origin',
      'Content-Security-Policy': "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; img-src data: https://tile.openstreetmap.org; base-uri 'none'; form-action 'none'; frame-ancestors 'none'" } });
  }
  if (!path.startsWith('/admin/api/')) return null;
  const name = path.slice('/admin/api/'.length);
  if (method === 'POST') {
    if (request.headers.get('X-Mava-Panel') !== '1') return adminFail(403, 'missing X-Mava-Panel header');
    let body = {};
    try { body = await request.json(); } catch (e) { /* empty */ }
    if (name === 'code') return sendCode(ctx, body);
    if (name === 'login') return login(ctx, body, url);
    const you = await sessionOf(ctx, request);
    if (!you) return adminFail(401, 'log in');
    if (name === 'logout') {
      await ctx.store.kvDel('session:' + cookieOf(request, COOKIE));
      return new Response(null, { status: 204, headers: { 'Set-Cookie': `${COOKIE}=; Path=/admin; Max-Age=0; HttpOnly; SameSite=Strict` } });
    }
    if (name === 'settings') return saveSettings(ctx, body);
    if (name === 'admins') return changeAdmins(ctx, body);
    if (name === 'restart') return adminJSON(200, { info: 'An edge relay has nothing to restart: saved settings apply at once.' });
    return adminFail(404, 'not on an edge relay');
  }
  if (method === 'GET') {
    const you = await sessionOf(ctx, request);
    if (!you) return adminFail(401, 'log in');
    if (name === 'state') return state(ctx, you, url);
    if (name === 'trip') return adminJSON(200, await tripPanelState(ctx));
    if (name === 'trip/reports') return tripReports(ctx, url);
  }
  return adminFail(404, 'not found');
}

async function sendCode(ctx, body) {
  let id;
  try { id = parseAccountID(body.id); } catch (e) { return adminFail(400, e.message); }
  // Same answer for non-admins: the panel doesn't tell who is an admin.
  const sent = { info: 'If this account is an admin of this relay, a code is on its way to it in Mava. It can take a minute.' };
  if (!(await ctx.admins()).includes(id)) return adminJSON(200, sent);
  if (await ctx.store.kvGet('code-wait:' + id)) return adminFail(429, 'A code was just sent. Wait a minute before asking again.');
  const pub = await ctx.relay.publicFor(id);
  if (!pub) return adminFail(409, "This relay doesn't know this account's keys yet. Open Mava with this relay in its relay list (it announces itself), then try again.");
  const code = Array.from(randomBytes(8), (b) => String(b % 10)).join('');
  await ctx.store.kvPut('code:' + id, JSON.stringify({ code, tries: 0 }), CODE_TTL);
  await ctx.store.kvPut('code-wait:' + id, '1', 60 * 1000);
  const me = await ctx.identity();
  const text = `Admin code for relay ${ctx.cfg.name}: ${code} (valid 10 min)`;
  const inner = cat(Uint8Array.of(0), u32be(Math.floor(Date.now() / 1000)), utf8(text));
  const idBytes = randomBytes(8), destBytes = unhex(id);
  const sealed = await noiseXSeal(me.xPriv, me.xPub, pub.x, dataPrologue(idBytes, destBytes), cat(me.edPub, inner));
  await ctx.relay.ingestOne(buildData(idBytes, destBytes, sealed, true), 'local', '', Date.now());
  return adminJSON(200, sent);
}

async function login(ctx, body, url) {
  let id;
  try { id = parseAccountID(body.id); } catch (e) { return adminFail(400, e.message); }
  const raw = await ctx.store.kvGet('code:' + id);
  const pc = raw ? JSON.parse(raw) : null;
  let ok = false;
  if (pc && pc.tries < 5 && (await ctx.admins()).includes(id)) {
    ok = String(body.code || '').trim() === pc.code;
    if (ok) await ctx.store.kvDel('code:' + id);
    else await ctx.store.kvPut('code:' + id, JSON.stringify({ code: pc.code, tries: pc.tries + 1 }), CODE_TTL);
  }
  if (!ok) return adminFail(401, 'Wrong or expired code. After 5 wrong tries, ask for a new one.');
  const tok = hex(randomBytes(32));
  await ctx.store.kvPut('session:' + tok, id, SESSION_TTL);
  const secure = url.protocol === 'https:' ? '; Secure' : '';
  return adminJSON(200, { admin: id }, { 'Set-Cookie': `${COOKIE}=${tok}; Path=/admin; Max-Age=${SESSION_TTL / 1000}; HttpOnly; SameSite=Strict${secure}` });
}

async function state(ctx, you, url) {
  const me = await ctx.identity();
  const s = await ctx.settings();
  const counts = await ctx.store.count();
  const started = Number((await ctx.store.kvGet('started')) || Date.now());
  const trip = await tripPanelState(ctx);
  return adminJSON(200, {
    you, owner: OWNER_ID, admins: await ctx.admins(), edge: ctx.platform,
    info: {
      Name: ctx.cfg.name, Region: ctx.cfg.region, Version: EDGE_VERSION + ' (' + ctx.platform + ')', PubKey: hex(me.bytes),
      Listen: url.origin, Peers: ctx.cfg.peers.map((p) => p.name), Started: new Date(started).toISOString(),
    },
    uptime: Math.floor((Date.now() - started) / 1000),
    stats: { Accepted: counts.total < 0 ? '—' : counts.total, Duplicate: '—', Rejected: '—', Purged: '—' },
    current: { pow_bits: s.powBits, ttl_hours: s.ttlHours, log: false, media_max_mb: 0, turn_enabled: false, media_accounts: [] },
    saved: s.saved, secure: url.protocol === 'https:',
    media: { on: false, used: 0, cap: 0, count: 0, files: [] },
    ledger: {}, turn: null, trip: trip.card ? trip : null,
  });
}

async function saveSettings(ctx, body) {
  const s = await ctx.settings();
  const saved = { ...s.saved };
  for (const [k, lo, hi] of [['pow_bits', 0, 28], ['ttl_hours', 1, 720]]) {
    if (body[k] === undefined || body[k] === null) { delete saved[k]; continue; }
    const v = Number(body[k]);
    if (!Number.isInteger(v) || v < lo || v > hi) return adminFail(400, `${k} must be ${lo}…${hi}`);
    saved[k] = v;
  }
  await ctx.store.kvPut('settings', JSON.stringify(saved));
  ctx._settings = null;
  return adminJSON(200, { info: 'Saved; it applies at once. (Media and TURN are not available on an edge relay.)' });
}

async function changeAdmins(ctx, body) {
  let list = JSON.parse((await ctx.store.kvGet('admins')) || '[]');
  try {
    if (body.add) list.push(parseAccountID(body.add));
    if (body.remove) {
      const id = parseAccountID(body.remove);
      if (id === OWNER_ID) return adminFail(403, "The owner can't be removed.");
      if (ctx.cfg.admins.includes(id)) return adminFail(403, "This admin is set in the relay's configuration (installer); change it there.");
      list = list.filter((a) => a !== id);
    }
  } catch (e) {
    return adminFail(400, e.message);
  }
  list = [...new Set(list)].filter((a) => a !== OWNER_ID);
  await ctx.store.kvPut('admins', JSON.stringify(list));
  ctx._admins = null; // re-read
  return adminJSON(200, { admins: await ctx.admins() });
}

async function tripReports(ctx, url) {
  const t = await currentTrip(ctx);
  if (!t) return adminFail(404, 'no trip');
  const after = Number(url.searchParams.get('after') || 0) || 0;
  const limit = 200;
  const { raws, cursor } = await ctx.relay.mailbox(t.hash, after, limit);
  return adminJSON(200, { packets: raws.map(b64), cursor, more: raws.length === limit });
}

// ---- src/federate.js ----
// Federation from the edge (relayclient.SyncOnce in Go): on a schedule, pull
// what each peer relay has and push what we have. Pushing needs the peer's
// sync token (we don't spend CPU on proof of work); without one, the peer
// pulls from us instead (list this relay among its peers).


const SYNC_PAGE = 500;
const SYNC_ROUNDS = 4;

async function peerFetch(ctx, peer, path, opts = {}) {
  const headers = { 'X-Origin': ctx.cfg.name, 'X-Region': ctx.cfg.region, ...(opts.headers || {}) };
  if (peer.token) headers.Authorization = 'Bearer ' + peer.token;
  const ac = new AbortController();
  const t = setTimeout(() => ac.abort(), 25000);
  try {
    return await fetch(peer.url.replace(/\/+$/, '') + path, { ...opts, headers, signal: ac.signal });
  } finally {
    clearTimeout(t);
  }
}

/** One sync round with one peer; returns {pulled, pushed}. */
async function syncPeer(ctx, peer) {
  const ckey = 'cursor:' + peer.name;
  const cur = JSON.parse((await ctx.store.kvGet(ckey)) || '{"a":0,"b":0}');
  let pulled = 0, pushed = 0;
  // Theirs → ours.
  for (let i = 0; i < SYNC_ROUNDS; i++) {
    const r = await peerFetch(ctx, peer, `/v1/sync/pull?after=${cur.b}&limit=${SYNC_PAGE}`);
    if (!r.ok) throw new Error(`pull from ${peer.name}: HTTP ${r.status}`);
    const items = decodeSync(new Uint8Array(await r.arrayBuffer()));
    pulled += await ctx.relay.ingestSync(items, 'peer:' + peer.name);
    cur.b = Number(r.headers.get('X-Cursor') || cur.b);
    if (r.headers.get('X-More') !== '1') break;
  }
  // Ours → theirs (only with a token).
  if (peer.token) {
    for (let i = 0; i < SYNC_ROUNDS; i++) {
      const { items, cursor, more } = await ctx.relay.pull(cur.a, SYNC_PAGE, 'peer:' + peer.name);
      if (items.length) {
        const r = await peerFetch(ctx, peer, '/v1/sync/push', {
          method: 'POST', body: encodeSync(items), headers: { 'Content-Type': 'application/x-meshmsg-frames' },
        });
        if (!r.ok) throw new Error(`push to ${peer.name}: HTTP ${r.status}`);
        pushed += items.length;
      }
      cur.a = cursor;
      if (!more) break;
    }
  }
  await ctx.store.kvPut(ckey, JSON.stringify(cur));
  return { pulled, pushed };
}

/** Periodic work: expire old packets, sync with peers. */
async function maintenance(ctx) {
  const out = { expired: 0, peers: {} };
  try { out.expired = await ctx.relay.expire(); } catch (e) { out.expireError = String(e); }
  for (const peer of ctx.cfg.peers) {
    try { out.peers[peer.name] = await syncPeer(ctx, peer); } catch (e) { out.peers[peer.name] = { error: String(e.message || e) }; }
  }
  return out;
}

// ---- src/api.js ----
// The relay's HTTP API (server/api in Go), for edge runtimes: the same
// paths, binary bodies and headers, so phones, desktops, boards and other
// relays use an edge relay like any other.


const EDGE_VERSION = '0.1.0';
const MAX_BODY = 4 << 20;
const PAGE = 500;

const CORS_HEADERS = 'Content-Type, X-PoW, X-Origin, X-Region, X-Nonce, X-Signature, X-Readers, X-Account, X-Day, Authorization';

function list(v) {
  if (Array.isArray(v)) return v.map(String).map((s) => s.trim()).filter(Boolean);
  return String(v || '').split(/[\s,]+/).map((s) => s.trim()).filter(Boolean);
}

/** Relay settings from the platform's variables (Cloudflare env / the Arvan bundle's CONFIG). */
function edgeConfig(env) {
  let peers = env.PEERS || [];
  if (typeof peers === 'string') { try { peers = JSON.parse(peers || '[]'); } catch (e) { peers = []; } }
  return {
    name: String(env.RELAY_NAME || 'edge'),
    region: String(env.RELAY_REGION || 'global'),
    publicURL: String(env.PUBLIC_URL || ''),
    admins: list(env.ADMINS).map((a) => a.toLowerCase()).filter((a) => /^[0-9a-f]{32}$/.test(a)),
    powBits: Number(env.POW_BITS ?? 16),
    ttlHours: Number(env.TTL_HOURS ?? 168),
    syncTokens: list(env.SYNC_TOKENS),
    peers: (Array.isArray(peers) ? peers : []).filter((p) => p && p.name && p.url),
    maxWait: Number(env.MAX_WAIT ?? 25),
    pollMs: Number(env.POLL_MS ?? 2000),
    releaseUpstream: String(env.RELEASE_UPSTREAM || 'https://eu-1.mfadem.ir'),
  };
}

/** Per-request context: store, settings, identity and admins. */
class EdgeCtx {
  constructor(store, cfg, platform, waitUntil) {
    this.store = store;
    this.cfg = cfg;
    this.platform = platform;
    this.waitUntil = waitUntil || ((p) => p.catch(() => {}));
    this.relay = new Relay(store, { name: cfg.name, region: cfg.region, ttlMs: () => this._ttlMs });
    this._ttlMs = cfg.ttlHours * 3600 * 1000;
  }

  async settings() {
    if (!this._settings) {
      let saved = {};
      try { saved = JSON.parse((await this.store.kvGet('settings')) || '{}'); } catch (e) { saved = {}; }
      this._settings = {
        saved,
        powBits: saved.pow_bits ?? this.cfg.powBits,
        ttlHours: saved.ttl_hours ?? this.cfg.ttlHours,
      };
      this._ttlMs = this._settings.ttlHours * 3600 * 1000;
    }
    return this._settings;
  }

  async admins() {
    if (!this._admins) {
      let saved = [];
      try { saved = JSON.parse((await this.store.kvGet('admins')) || '[]'); } catch (e) { saved = []; }
      this._admins = [...new Set([OWNER_ID, ...this.cfg.admins, ...saved])];
    }
    return this._admins;
  }

  /** The relay's own key (made on first use, kept in the store). */
  async identity() {
    if (!edgeIdentityCache.has(this.store)) {
      const seedHex = await this.store.kvPutIfAbsent('identity', hex(randomBytes(64)));
      const seed = unhex(seedHex);
      const xPriv = seed.slice(0, 32), edSeed = seed.slice(32);
      const xPub = x25519(xPriv, X25519_BASE), edPub = await edPublic(edSeed);
      await this.store.kvPutIfAbsent('started', String(Date.now()));
      edgeIdentityCache.set(this.store, { xPriv, xPub, edSeed, edPub, bytes: cat(xPub, edPub) });
    }
    return edgeIdentityCache.get(this.store);
  }
}
const edgeIdentityCache = new WeakMap();

function respond(body, status = 200, headers = {}) { return new Response(body, { status, headers }); }
function jsonOK(v) { return respond(JSON.stringify(v), 200, { 'Content-Type': 'application/json' }); }
function textErr(status, msg) { return respond(msg + '\n', status, { 'Content-Type': 'text/plain; charset=utf-8' }); }
function framesOK(body, cursor, more) {
  const h = { 'Content-Type': 'application/x-meshmsg-frames', 'X-Cursor': String(cursor) };
  if (more) h['X-More'] = '1';
  return respond(body, 200, h);
}

async function readBody(request) {
  const b = new Uint8Array(await request.arrayBuffer());
  if (b.length > MAX_BODY) throw new Error('body too large');
  return b;
}

function origin(request, prefix) {
  let o = request.headers.get('X-Origin') || '';
  if (!o) return prefix + 'anon';
  if (o.length > 64) o = o.slice(0, 64);
  return prefix + o;
}

async function powOK(ctx, request, body) {
  const s = await ctx.settings();
  if (s.powBits <= 0 || body.length === 0) return true;
  return checkPoW(body, request.headers.get('X-PoW'), s.powBits);
}

function syncAuthorized(ctx, request) {
  const h = request.headers.get('Authorization') || '';
  if (!h.startsWith('Bearer ')) return null; // fall back to proof of work
  return ctx.cfg.syncTokens.includes(h.slice(7));
}

/** Long poll: calls fetch until it returns something or wait (s) elapses. */
async function waitFor(ctx, url, fetchOnce) {
  const wait = Math.min(Math.max(Number(url.searchParams.get('wait') || 0), 0), ctx.cfg.maxWait) * 1000;
  const deadline = Date.now() + wait;
  for (;;) {
    const r = await fetchOnce();
    if (r.found || Date.now() + ctx.cfg.pollMs > deadline) return r;
    await sleep(ctx.cfg.pollMs);
  }
}

// Go's encoding/json escapes these; signatures cover Go-style JSON.
function goJSON(v) {
  return JSON.stringify(v).replace(/[<>&\u2028\u2029]/g, (c) => '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0'));
}

async function relayList(ctx, url) {
  const me = await ctx.identity();
  const pub = hex(me.bytes);
  const urls = ctx.cfg.publicURL ? [ctx.cfg.publicURL] : [url.origin];
  const relays = [{ name: ctx.cfg.name, region: ctx.cfg.region, urls, pubkey: pub }];
  const issued = Math.floor(Date.now() / 1000);
  const payload = goJSON({ relays, issued });
  const sig = await signDomain(me.edSeed, 'MESHMSG-RELAYS', utf8(payload));
  return jsonOK({ relays, issued, pubkey: pub, signature: hex(sig) });
}

const releaseCache = new Map(); // channel → {at, body}
async function release(ctx, url) {
  const ch = url.searchParams.get('channel') || 'stable';
  if (ch !== 'beta' && ch !== 'stable') return textErr(400, 'unknown channel');
  const c = releaseCache.get(ch);
  if (c && Date.now() - c.at < 10 * 60 * 1000) return respond(c.body, 200, { 'Content-Type': 'application/json', 'Cache-Control': 'public, max-age=600' });
  try {
    const r = await fetch(ctx.cfg.releaseUpstream.replace(/\/+$/, '') + '/v1/release?channel=' + ch);
    if (r.ok) {
      const body = await r.text();
      releaseCache.set(ch, { at: Date.now(), body });
      return respond(body, 200, { 'Content-Type': 'application/json', 'Cache-Control': 'public, max-age=600' });
    }
  } catch (e) { /* below */ }
  return textErr(404, 'no release manifest yet');
}

async function route(ctx, request, url) {
  const m = request.method, p = url.pathname;
  const q = (name, def = 0) => { const v = Number(url.searchParams.get(name)); return Number.isFinite(v) && url.searchParams.has(name) ? v : def; };

  if (m === 'GET' && p === '/v1/info') {
    const me = await ctx.identity();
    const s = await ctx.settings();
    return jsonOK({ name: ctx.cfg.name, region: ctx.cfg.region, pow_bits: s.powBits, version: EDGE_VERSION, pubkey: hex(me.bytes) });
  }
  if (m === 'GET' && p === '/v1/relays') return relayList(ctx, url);
  if (m === 'POST' && p === '/v1/packets') {
    const body = await readBody(request);
    if (!(await powOK(ctx, request, body))) return textErr(402, 'proof of work required');
    let raws;
    try { raws = decodeFrames(body); } catch (e) { return textErr(400, 'bad frames'); }
    await ctx.settings();
    return jsonOK({ accepted: await ctx.relay.ingest(raws, origin(request, 'client:'), ctx.cfg.region) });
  }
  if (m === 'POST' && p === '/v1/receipts/query') {
    const body = await readBody(request);
    if (body.length % 8 || body.length / 8 > 1000) return textErr(400, 'body must be up to 1000 packet IDs');
    const ids = [];
    for (let i = 0; i < body.length; i += 8) ids.push(hex(body.subarray(i, i + 8)));
    return framesOK(encodeFrames(await ctx.relay.receipts(ids)), 0, false);
  }
  if (m === 'GET' && p === '/v1/challenge') return respond(await ctx.relay.newChallenge(), 200, { 'Content-Type': 'text/plain' });
  if (m === 'GET' && p.startsWith('/v1/mailbox/')) {
    const dest = p.slice('/v1/mailbox/'.length).toLowerCase();
    if (!/^[0-9a-f]{32}$/.test(dest)) return textErr(400, 'bad destination');
    let sig;
    try { sig = unhex(request.headers.get('X-Signature') || ''); } catch (e) { sig = new Uint8Array(0); }
    if (!(await ctx.relay.authorizeFetch(dest, request.headers.get('X-Nonce') || '', sig))) return textErr(401, 'unauthorized');
    const after = q('after');
    const r = await waitFor(ctx, url, async () => {
      const x = await ctx.relay.mailbox(dest, after, PAGE);
      return { ...x, found: x.raws.length > 0 };
    });
    return framesOK(encodeFrames(r.raws), r.cursor, false);
  }
  if (m === 'POST' && p === '/v1/gateway') {
    const body = await readBody(request);
    let g;
    try { g = decodeGateway(body); } catch (e) { return textErr(400, 'bad gateway body'); }
    const org = origin(request, 'gw:');
    await ctx.settings();
    if (g.upload.length > 0) {
      if (!(await powOK(ctx, request, body))) return textErr(402, 'proof of work required');
      await ctx.relay.ingest(g.upload, org, ctx.cfg.region);
    }
    const req = { origin: org, serve: g.serve, after: q('after'), carrier: url.searchParams.get('carrier') === '1', quota: q('quota'), limit: PAGE };
    const r = await waitFor(ctx, url, async () => {
      ctx.relay.annCache.clear();
      const x = await ctx.relay.gateway(req);
      return { ...x, found: x.raws.length > 0 };
    });
    return framesOK(encodeFrames(r.raws), r.cursor, false);
  }
  if (m === 'POST' && p === '/v1/sync/push') {
    const body = await readBody(request);
    const tok = syncAuthorized(ctx, request);
    if (tok === false) return textErr(401, 'bad token');
    if (tok === null && !(await powOK(ctx, request, body))) return textErr(402, 'proof of work required');
    let items;
    try { items = decodeSync(body); } catch (e) { return textErr(400, 'bad sync body'); }
    await ctx.settings();
    return jsonOK({ accepted: await ctx.relay.ingestSync(items, origin(request, 'peer:')) });
  }
  if (m === 'GET' && p === '/v1/sync/pull') {
    if (syncAuthorized(ctx, request) === false) return textErr(401, 'bad token');
    const after = q('after'), limit = Math.min(Math.max(q('limit', PAGE), 1), 2000);
    const ex = origin(request, 'peer:');
    const r = await waitFor(ctx, url, async () => {
      const x = await ctx.relay.pull(after, limit, ex);
      return { ...x, found: x.items.length > 0 };
    });
    return framesOK(encodeSync(r.items), r.cursor, r.more);
  }
  if (m === 'GET' && p === '/v1/release') return release(ctx, url);
  if (m === 'GET' && p === '/v1/trip') return tripGet(ctx);
  if (m === 'PUT' && p === '/v1/trip') return tripPut(ctx, request);
  if (m === 'DELETE' && p === '/v1/trip') return tripDelete(ctx, request, url);
  if (p === '/admin' || p.startsWith('/admin/')) {
    const r = await adminRoute(ctx, request, url);
    if (r) return r;
  }
  if (m === 'GET' && p === '/') return respond(`Mava relay ${ctx.cfg.name} (edge, ${ctx.platform}). Add its address to Mava; admins: /admin\n`, 200, { 'Content-Type': 'text/plain; charset=utf-8' });
  return textErr(404, 'not found');
}

/** Handles one request (both platforms). */
async function handleEdge(ctx, request) {
  const url = new URL(request.url);
  const cors = { 'Access-Control-Allow-Origin': '*', 'Access-Control-Expose-Headers': 'X-Cursor, X-More' };
  if (request.method === 'OPTIONS') {
    return respond(null, 204, { ...cors, 'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE', 'Access-Control-Allow-Headers': CORS_HEADERS, 'Access-Control-Max-Age': '86400' });
  }
  let res;
  try {
    res = await route(ctx, request, url);
  } catch (e) {
    res = textErr(e.message === 'body too large' ? 413 : 500, e.message === 'body too large' ? e.message : 'relay error: ' + (e.message || e));
  }
  const h = new Headers(res.headers);
  for (const [k, v] of Object.entries(cors)) h.set(k, v);
  if (!h.has('Cache-Control')) h.set('Cache-Control', 'no-store');
  return new Response(res.body, { status: res.status, headers: h });
}

/** Expiry and federation (a cron trigger, or now and then on platforms without one). */
async function runMaintenance(ctx) {
  await ctx.settings();
  return maintenance(ctx);
}

function makeStore(env) {
  if (env.DB) return new D1Store(env.DB);
  if (env.S3 && env.S3.bucket) return new S3Store(env.S3);
  throw new Error('no store: bind a D1 database as DB (Cloudflare) or set S3 (endpoint, region, bucket, accessKey, secretKey)');
}

// ---- ArvanCloud Edge Computing entry (service worker) ----
// The installer replaces the CONFIG object below with this relay's settings
// (name, region, admins, the Object Storage bucket and its keys). Arvan's
// edge has no scheduler: expiry and federation run now and then, after a
// request, at most once a minute per instance.

const CONFIG = /*MAVA_CONFIG*/ {} /*END_MAVA_CONFIG*/;

let lastMaintenance = 0;

function arvanCtx(event) {
  const wait = typeof event.waitUntil === 'function' ? (p) => event.waitUntil(p) : (p) => { p.catch(() => {}); };
  return new EdgeCtx(makeStore(CONFIG), edgeConfig(CONFIG), 'arvan', wait);
}

addEventListener('fetch', (event) => {
  const ctx = arvanCtx(event);
  event.respondWith(handleEdge(ctx, event.request).then((res) => {
    if (Date.now() - lastMaintenance > 60000) {
      lastMaintenance = Date.now();
      ctx.waitUntil(runMaintenance(new EdgeCtx(ctx.store, ctx.cfg, 'arvan', ctx.waitUntil)));
    }
    return res;
  }));
});
